// ===== Mephisto · i6 · x_i6_model.js — one model conversation per station („So hätte es klingen können“), shown after a run and used by tests/i6_node.js
// (every model run must reach ≥ 17/20). The doctor's turns only; {LAST} = the learner's surname. Level: the station's level.
var BV_MODEL={
bv01:["Guten Abend. Ja, ich bin Doktor {LAST}.","B wie Berta, E wie Emil, R wie Richard, G wie Gustav, E wie Emil, R wie Richard.","Ich bin Allgemeinarzt.","Einen Kaffee, bitte. Danke.",
 "Guten Abend, ich bin Doktor {LAST}. Ich bin der Arzt hier.","Wie heißen Sie?","Was ist passiert?","Wo genau ist die Wunde?","@ Ich glaube, ein Pflaster ist zu klein. Wir nähen die Wunde, das geht schnell.","Wann ist das passiert?","Was haben Sie gemacht? Womit haben Sie sich geschnitten?","Das tut mir leid. Das verstehe ich gut.","Wann war Ihre letzte Tetanusimpfung?","Nehmen Sie Medikamente? Welche?","Haben Sie noch Fragen?"],
bv02:["Hundertzweiundachtzig zu achtundneunzig, Puls vierundneunzig.","Hundertsiebenundsechzig.","Guten Tag, Herr Heckmann. Ich bin Doktor {LAST}.","Wann sind Sie geboren?","Wie groß sind Sie, und wie viel wiegen Sie?","Was führt Sie heute zu uns?","Seit wann haben Sie das?","Welchen Wert haben Sie zu Hause gemessen? Wann?","@ Der Blutdruck ist zu hoch. Wir geben Ihnen eine Tablette und kontrollieren ihn heute noch einmal.","Das tut mir leid. Ich verstehe, dass Sie Angst haben.","Welche Medikamente nehmen Sie? Haben Sie die Tabletten heute genommen?","Können Sie gut sehen und sprechen? Haben Sie eine Lähmung oder ein Kribbeln?","Wie viel Alkohol haben Sie gestern getrunken?","Wer ist Ihr Hausarzt?","Haben Sie noch Fragen?"],
bv03:["Guten Tag, ich bin Doktor {LAST}. Was ist passiert?","Wo genau ist die Wunde?","Wann ist das passiert?","Wie ist das passiert?","Das ist nicht Ihre Schuld. Das kann jedem passieren.","Hatte er einen Helm?","Hallo Emil. Ich schaue nur. Tut es weh?","@ Nein, er bekommt keine Spritze. Wir kleben die Wunde, das tut nicht weh.","War er bewusstlos? Hat er sofort geweint?","Hat er erbrochen?","Kann er den Mund öffnen? Sind die Zähne in Ordnung?","Ist er gegen Tetanus geimpft?","Haben Sie noch Fragen?"],
bv04:["Guten Tag, ich bin Doktor {LAST}. Ich bin Arzt.","Wie geht es Ihnen?","Das tut mir leid. Ich bin bei Ihnen.","Ich heiße Doktor {LAST}.","Wie heißen Sie?","Wann sind Sie geboren?","Wo tut es weh?","Seit wann haben Sie das?","Bekommen Sie gut Luft?","Haben Sie Allergien?","Was waren Sie von Beruf?","Ich komme gleich wieder. Ich bleibe in der Nähe."],
bv05:["Guten Tag, Herr Heckmann, ich bin Doktor {LAST}. Darf ich Sie untersuchen?","Haben Sie Fieber? Haben Sie Husten mit Auswurf?","Machen Sie bitte den Oberkörper frei.","Setzen Sie sich bitte hin.","Ich höre jetzt Ihre Lunge ab. Das Stethoskop ist ein bisschen kalt.","Atmen Sie bitte tief ein und aus.","@ Ich höre rechts unten ein Rasseln. Das kann eine Lungenentzündung sein, wir machen ein Röntgenbild.","Halten Sie bitte die Luft an.","Husten Sie bitte einmal.","Sagen Sie bitte neunundneunzig.","Machen Sie bitte den Mund auf und sagen Sie Aaah.","Legen Sie sich bitte hin.","Das tut mir leid, drei Nächte ohne Schlaf sind sehr anstrengend.","Ich möchte jetzt Ihren Bauch abtasten. Sagen Sie bitte, wenn es wehtut.","Sie können sich wieder anziehen."],
bv06:["Guten Abend, ich bin Doktor {LAST}. Ja, ich übernehme. Ich habe noch ein paar Fragen.","Wann haben Sie ihn gefunden?","Ist er gestürzt? Hat jemand etwas gesehen?","War er bewusstlos?","Hat er erbrochen?","Das tut mir leid. Das klingt sehr traurig.","Was haben Sie ihm gegeben?","@ Er kommt in Koje sechs.","Wie waren die Werte? Blutdruck, Puls, Zucker?","Haben Sie einen Alkoholtest gemacht?","Kennen Sie ihn? War er schon einmal hier?","Hat er Angehörige? Wen können wir anrufen?","Hat er über Schmerzen im Nacken geklagt?","Ich fasse zusammen: Er ist gestürzt, war kurz bewusstlos und hat einmal erbrochen.","Danke, auf Wiedersehen."],
bv07:["Guten Tag, Frau Brandt, ich bin Doktor {LAST}. Wir schauen uns jetzt zusammen Ihre Tabletten an.","Was ist das für eine Tablette?","Wofür nehmen Sie diese?","Und die nächste?","Und die nächste?","Und die nächste?","Und die nächste?","Und die nächste?","Und die nächste?","Haben Sie Allergien?","Nehmen Sie noch etwas ohne Rezept, zum Beispiel Schmerzmittel?","@ Ja, Ibuprofen ist nicht gut für Ihr Herz und die Nieren. Nehmen Sie lieber Paracetamol.","Nehmen Sie alle Tabletten jeden Tag?","Das verstehe ich gut. Sie möchten ohne Angst in die Stadt gehen.","Wer stellt Ihren Medikamentenplan zusammen?","Ich wiederhole: morgens Bisoprolol, Ramipril, Torasemid, Spironolacton und Apixaban, abends Ramipril, Apixaban und Atorvastatin. Habe ich das richtig verstanden?","Haben Sie noch Fragen?"],
bv08:["Guten Morgen, Frau Brandt. Ich bin Doktor {LAST}.","Wo genau fehlt Ihnen die Luft?","Seit wann haben Sie das?","Das tut mir leid. Sie haben Angst, dass es bei Ihnen auch so ist.","Wie fühlt es sich an?","Wie stark ist es, von null bis zehn?","@ Das weiß ich noch nicht sicher. Es kann auch vom Herzen kommen. Ich untersuche Sie gleich.","Was macht es besser oder schlimmer?","Sind die Beine geschwollen? Seit wann?","Haben Sie Appetit?","Haben Sie zugenommen? Wie viel? Haben Sie sich gewogen?","Müssen Sie nachts zur Toilette? Wie oft?","Haben Sie auch nachts Luftnot?","Haben Sie noch Fragen?"],
bv09:["Guten Tag, Herr Heckmann, ich bin Doktor {LAST}. Erzählen Sie bitte, was passiert ist.","Seit wann haben Sie die Schmerzen?","Wo genau tut es weh?","Wie fühlt sich der Schmerz an?","Strahlt der Schmerz aus?","Wie stark ist der Schmerz, von null bis zehn?","Haben Sie geschwitzt? Ist Ihnen übel?","Bekommen Sie gut Luft?","Entschuldigung, das Wort kenne ich nicht. Meinen Sie, Sie sind schwindelig?","@ Es kann ein Herzinfarkt sein. Ich nehme das sehr ernst, wir machen sofort ein EKG und nehmen Blut ab.","Hatten Sie so etwas schon einmal?","Haben Sie selbst schon etwas dagegen genommen?","Jetzt habe ich noch ein paar Fragen zu Ihren Medikamenten.","Haben Sie in den letzten 24 Stunden ein Potenzmittel genommen? Ich frage das, weil es für die Behandlung wichtig ist.","Rauchen Sie?","Gibt es Krankheiten in Ihrer Familie?","Das tut mir sehr leid. Das muss schlimm für Sie gewesen sein.","Wie alt war Ihr Vater?","Ich fasse kurz zusammen: Seit zwei Stunden haben Sie einen Druck in der Brust, der in den linken Arm zieht. Stimmt das so?"],
bv10:["Guten Abend, ich bin Doktor {LAST}. Ich möchte Ihnen helfen.","Ich sehe, dass Sie wütend sind. Sie wollen hier raus.","Bitte schreien Sie nicht. Ich bleibe beim Sie.","Möchten Sie sich setzen? Möchten Sie ein Glas Wasser?","Ihre Wunde am Kopf muss genäht werden. Das dauert zehn Minuten.","@ Ich kann Sie nicht festhalten. Ich empfehle Ihnen aber, erst die Wunde nähen zu lassen und hierzubleiben. Sie entscheiden.","Möchten Sie lieber jetzt nähen oder erst ein Glas Wasser trinken?","Wer wartet auf Sie? Ihre Tochter?","Das tut mir leid. Das klingt sehr belastend für Sie.","Wann haben Sie zuletzt getrunken? Wie viel trinken Sie am Tag?","Hatten Sie schon einmal einen Krampfanfall, wenn Sie nicht getrunken haben?","Nehmen Sie andere Drogen?","Haben Sie Kopfschmerzen?","Wir haben eine Suchtberatung. Ich kann Ihnen eine Nummer geben, wenn Sie Hilfe möchten."],
bv11:["Notaufnahme, Doktor {LAST}, guten Morgen.","Ich verstehe, dass Sie sich Sorgen machen. Ich unterliege aber der Schweigepflicht. Ich muss zuerst Ihre Mutter fragen.","Ihre Mutter ist einverstanden. Sie ist heute Nacht gekommen, weil sie schlecht Luft bekommen hat. Das Herz ist zu schwach, deshalb ist Wasser in der Lunge. Es geht ihr schon besser.","Wann haben Sie Ihre Mutter zuletzt gesehen? Was ist Ihnen aufgefallen?","Das ist nicht Ihre Schuld. Gut, dass Sie es mir jetzt sagen.","@ Ihre Mutter ist stabil. Sie müssen nicht sofort losfahren, kommen Sie heute nach der Schule.","Nimmt sie ihre Tabletten regelmäßig?","Was isst Ihre Mutter? Isst sie salzig?","Wer hilft ihr zu Hause? Kommt sie allein zurecht?","Gibt es eine Patientenverfügung oder eine Vorsorgevollmacht?","Wie kann ich Sie erreichen? Wie ist Ihre Telefonnummer?","Ich fasse zusammen: Ihre Mutter bleibt bei uns, und Sie kommen heute Nachmittag.","Sie können heute jederzeit zu Besuch kommen. Ich rufe Sie an, wenn sich etwas ändert."],
bv12:["Guten Morgen, Frau Brandt. Ich bin Doktor {LAST}, der diensthabende Arzt.","Erzählen Sie bitte, was passiert ist.","Seit wann haben Sie die Luftnot?","Wird es besser, wenn Sie sitzen?","Das tut mir leid, das war sicher eine schlimme Nacht.","Mit wie vielen Kissen schlafen Sie?","Das klingt sehr belastend. Ich kann verstehen, dass Ihnen das Angst macht.","@ Ich wünschte, ich könnte Ihnen diese Angst einfach nehmen. Sicher sagen kann ich es Ihnen heute noch nicht, das wäre nicht ehrlich. Aber ich bleibe bei Ihnen.","Haben Sie Husten oder Auswurf?","Sind die Beine geschwollen? Haben Sie zugenommen?","Hatten Sie so etwas schon einmal?","Jetzt habe ich noch einige Fragen zu Ihren Medikamenten.","Nehmen Sie Ihre Medikamente jeden Tag, oder haben Sie etwas weggelassen?","Was essen Sie normalerweise? Kochen Sie mit viel Salz?","Was macht Ihnen am meisten Sorgen?","Darf ich kurz zusammenfassen? Sie haben seit drei Tagen Luftnot, und seit gestern auch im Liegen. Stimmt das so?","Haben Sie noch Fragen?"],
bv13:["Das muss furchtbar für Sie gewesen sein. Jetzt ist er hier, und wir kümmern uns um ihn.","Guten Abend, ich bin Doktor {LAST}.","Was ist passiert?","In welcher Situation hat es angefangen?","Wie lange hat der Anfall gedauert? Haben Sie auf die Uhr geschaut, oder Ihr Mann?","Wie waren die Augen?","War er blau? Wie hat er geatmet?","Das muss sehr schlimm gewesen sein. Ich verstehe, dass Sie Angst hatten.","Hat der ganze Körper gezuckt, oder nur eine Seite?","Wie war er danach?","Hat er einen Ausschlag? Kann er das Kinn auf die Brust legen?","Ist er geimpft?","Haben Sie schon etwas gegen das Fieber versucht? Hat es geholfen?","Gibt es Krampfanfälle in Ihrer Familie?","Hallo Emil. Ich schaue nur in dein Ohr.","Das war ein Fieberkrampf. Das sieht schlimm aus, schadet dem Gehirn aber nicht.","@ Nein, das ist keine Epilepsie. Fieberkrämpfe kommen häufig vor und hören meistens bis zum Schulalter auf.","Wir möchten ihn heute Nacht hierbehalten und beobachten.","Wenn es wieder passiert: auf die Seite legen, nichts in den Mund und auf die Uhr schauen. Bei mehr als fünf Minuten die 112 anrufen.","Können Sie mir bitte in Ihren eigenen Worten sagen, was Sie tun, wenn es wieder passiert?"],
bv14:["Guten Tag, Herr Dr. Lohse. Ich bin Doktor {LAST}.","Das ist Ihr gutes Recht. Ich kann Sie nicht festhalten.","@ Schlimmstenfalls können Sie innerlich verbluten. Das ist lebensgefährlich.","Ich sehe, dass Sie das sehr beunruhigt.","Darf ich fragen, was Sie daran hindert, hierzubleiben?","Das verstehe ich gut. Sie kümmern sich seit Jahren allein um Ihre Frau. Das ist eine große Leistung.","Gibt es jemanden, der sich heute Nacht um Ihre Frau kümmern könnte? Eine Nachbarin?","Wir könnten den Sozialdienst anrufen und eine Kurzzeitpflege für Ihre Frau organisieren.","Man kann innerlich verbluten, wenn die Blutung im Magen weitergeht.","Wie sieht Ihr Stuhlgang aus? Welche Farbe, wie oft?","Nehmen Sie Schmerzmittel?","Waren Sie bewusstlos, oder sind Sie umgekippt?","Ist Ihnen übel? Haben Sie Blut erbrochen?","Wenigstens eine Magenspiegelung heute noch – dann sehen wir weiter.","Wenn der Stuhl wieder schwarz wird oder Ihnen schwindelig wird, kommen Sie bitte sofort wieder oder rufen die 112.","Können Sie mir bitte in Ihren eigenen Worten sagen, was wir besprochen haben?"],
bv15:["Danke für den Anruf. Ich komme sofort.","Bitte Oberkörper hoch, Beine tief, und mehr Sauerstoff über die Maske – Ziel 88 bis 92 Prozent.","40 Milligramm Furosemid i.v., bitte, dazu eine BGA und ein EKG.","{LAST}, Notaufnahme. Es geht um Frau Brandt, 71 Jahre, Bett vier.","Atemfrequenz 28, Sättigung 86 Prozent unter vier Litern, Puls 132, Druck 96 zu 58, NEWS 13.","Sie ist seit gestern Nacht hier mit kardialer Dekompensation bei Herzinsuffizienz und Vorhofflimmern.","Ich gehe von einem Lungenödem aus.","Ich bitte Sie zu kommen. Ich möchte eine NIV beginnen und sie auf die Intensivstation verlegen.","Welche Einstellung soll ich für die CPAP nehmen?","@ Frau Brandt, ich bin bei Ihnen. Die Maske hilft Ihnen beim Atmen, der Oberarzt kommt gleich.","Soll ich Nitro geben?","Wer informiert die Tochter?","Sagen Sie ihr bitte, ich bin gleich da. Danke, dass Sie mir das sagen.","Gibt es eine Patientenverfügung?","Ich wiederhole: CPAP mit PEEP fünf bis acht, kein Nitrat, die Tochter nach dem Beginn der Maske."],
bv16:["Guten Morgen, Frau Brandt. Ich bin Doktor {LAST}. Darf ich mich zu Ihnen setzen?","Was macht Ihnen dabei Angst?","Das tut mir sehr leid. Ich verstehe, dass Sie nach dieser Erfahrung Angst haben.","Ihr Mann hatte eine andere Krankheit. Bei Ihnen ist es anders.","Ihr Herz pumpt zu schwach, deshalb staut sich Wasser zurück, auch neben der Lunge.","Wir möchten das Wasser mit einer dünnen Nadel zwischen den Rippen abziehen.","Damit Sie wieder besser Luft bekommen.","Sie sitzen dabei, bekommen eine örtliche Betäubung, und ich schaue vorher mit dem Ultraschall. Es dauert etwa fünfzehn Minuten.","Mögliche Risiken sind ein Bluterguss, eine Entzündung oder Luft neben der Lunge. Das ist selten.","@ An Ihrer Stelle würde ich es machen lassen. Ich empfehle es Ihnen.","Die andere Möglichkeit wäre, mehr Wassertabletten zu geben und abzuwarten.","Sie müssen das nicht sofort entscheiden. Überlegen Sie in Ruhe bis morgen früh.","Zu Hause wiegen Sie sich bitte jeden Morgen auf der Waage.","Und die Wassertablette dürfen Sie mittags nehmen, wenn Sie vom Kurs zurück sind – aber bitte jeden Tag.","Wenn Sie mehr als zwei Kilo in drei Tagen zunehmen, rufen Sie bitte sofort Frau Doktor Seitz an.","Können Sie mir bitte in Ihren eigenen Worten sagen, was morgen passiert?","@ Ich wünschte, ich könnte Ihnen sagen, dass Ihr Herz wieder ganz gesund wird. Das wäre nicht ehrlich. Aber wir können viel tun, damit Sie gut damit leben.","Möchten Sie den Bogen jetzt unterschreiben, oder lieber morgen früh?"],
bv17:["Guten Tag, Frau Brandt. Ich bin Doktor {LAST}, ich bin der Arzt in der Notaufnahme.","Wie heißen Sie mit vollem Namen? Können Sie Ihren Namen bitte buchstabieren?","Wann sind Sie geboren?","Wie groß sind Sie, und wie viel wiegen Sie?","@ Entschuldigung, ich meine: Wie viel wiegen Sie heute?","Was führt Sie zu uns? Erzählen Sie bitte.","Seit wann haben Sie die Luftnot?","Was macht es besser, was macht es schlimmer?","Haben Sie Husten oder Auswurf?","Sind Ihre Beine geschwollen?","Mit wie vielen Kissen schlafen Sie?","Haben Sie zugenommen? Wie viel, in welcher Zeit?","Wie ist Ihr Appetit?","Ist der Stuhlgang normal?","Jetzt habe ich noch einige Fragen zu Ihren Vorerkrankungen.","Haben Sie Vorerkrankungen?","Sind Sie schon einmal operiert worden?","Welche Medikamente nehmen Sie? Nehmen Sie alle jeden Tag, oder haben Sie etwas vergessen?","Haben Sie Allergien?","Rauchen Sie? Trinken Sie Alkohol?","Gibt es Krankheiten in Ihrer Familie?","Das tut mir leid. Danke, dass Sie mir das erzählen.","Leben Sie allein? Wer hilft Ihnen?","Was macht Ihnen am meisten Sorgen?","Können Sie bitte etwas langsamer sprechen?","Darf ich kurz zusammenfassen? Sie haben seit drei Tagen zunehmende Luftnot, seit gestern auch im Liegen. Stimmt das so?","Ich vermute, dass Ihr Herz zu schwach pumpt und sich deshalb Wasser in der Lunge sammelt.","@ Ja, wahrscheinlich ist es wieder das Herz. Es pumpt zu schwach, deshalb sammelt sich Wasser in der Lunge.","Wir werden Blut abnehmen, ein EKG schreiben und Ihr Herz mit Ultraschall untersuchen.","@ Nein, das tut nicht weh. Ich lege einen Schallkopf mit etwas Gel auf die Brust, und wir sehen Ihr Herz auf dem Bildschirm.","Ich bespreche das gleich mit meinem Oberarzt.","@ Ja, Sie bleiben ein paar Tage bei uns. Wir rufen Frau Lehmann an, damit sie sich um Ihren Hund kümmert.","Haben Sie noch Fragen?"],
bv18:["Guten Abend, Herr Maurer. Ich bin Doktor {LAST}.","Setzen wir uns bitte. Ich möchte in Ruhe mit Ihnen sprechen.","Was hat man Ihnen bisher gesagt?","Das tut mir sehr leid. Das muss sehr schwer für Sie sein.","Möchten Sie, dass ich ganz offen mit Ihnen spreche?","Ich muss Ihnen leider etwas sehr Schweres sagen.","Ihre Mutter wird wahrscheinlich in dieser Nacht sterben.","@ Nein, sie leidet nicht. Wir geben ihr ein starkes Schmerzmittel, damit sie keine Schmerzen und keine Atemnot hat.","(schweigt)","Wir möchten jetzt vor allem ihre Beschwerden lindern, damit sie nicht leidet.","@ Nein. Sie haben nichts falsch gemacht. Es ist die Krankheit.","Was hätte Ihre Mutter gewollt? Gibt es eine Patientenverfügung?","Wir werden sie nicht auf die Intensivstation verlegen und nicht wiederbeleben, so wie sie es verfügt hat.","Sie können die ganze Nacht bei ihr bleiben.","Sprechen Sie ruhig mit ihr. Sie hört Sie vielleicht noch.","Gibt es jemanden, den wir anrufen sollen? Haben Sie Geschwister?","Ich komme in einer Stunde wieder vorbei, und Sie können jederzeit klingeln."],
bv19:["Koje sechs: Herr Kästner, 41, bekannte Alkoholabhängigkeit. Heute früh um halb fünf hatte er zu Hause einen generalisierten Krampfanfall im Entzug; die Nachbarin hat den Rettungsdienst gerufen.","Seit drei Tagen. Er hat von sich aus aufgehört, wegen seiner Tochter.","Wach, zeitlich unscharf orientiert, feinschlägiger Tremor, schweißig. Puls 118, Druck 164 zu 98, Temperatur 37,9. Er sieht Käfer an der Wand. CIWA-Ar 24.","Zwei Milligramm Lorazepam i.v. um fünf und noch einmal um sechs, 100 Milligramm Thiamin i.v. vor der Glukose, eine Vollelektrolytlösung läuft.","Offen sind drei Dinge: Das Kalium war 3,1 – Substitution läuft, Kontrolle um acht. Magnesium ist angeordnet, aber noch nicht angehängt. Das Bett auf der Überwachungsstation ist zugesagt, aber noch nicht frei. Und bitte den Sozialdienst wegen der Tochter.","Herr Kästner ist ein 41-jähriger Patient mit bekannter Alkoholabhängigkeit, der heute um 04:30 Uhr nach dreitägiger Abstinenz einen generalisierten Krampfanfall erlitt. Bei Aufnahme war er zeitlich unscharf orientiert, tachykard und hyperton mit Tremor und optischen Halluzinationen, CIWA-Ar 24 Punkte. Ich gehe von einem schweren Alkoholentzugssyndrom mit Entzugskrampf und beginnendem Delir aus. Er erhielt Lorazepam, Thiamin und Volumen. Ich empfehle die Aufnahme auf die Überwachungsstation.","Um eine Wernicke-Enzephalopathie zu verhindern: Glukose verbraucht Thiamin, und bei einem Mangel kann die Glukosegabe sie auslösen.","Im beginnenden Delir ist er nach meiner Einschätzung nicht einwilligungsfähig. Bei akuter Eigengefährdung müssten wir den psychiatrischen Dienst hinzuziehen und gegebenenfalls eine Unterbringung nach dem PsychKHG einleiten.","Schwester Hilde, wie war die Nacht? Hat er geschlafen?","@ Nein, nicht sofort fixieren. Zuerst deeskalieren, eine Sitzwache und Medikamente. Eine Fixierung nur als letztes Mittel und mit richterlicher Genehmigung.","Das tut mir leid, das war eine harte Nacht für Sie.","Weiß die Familie Bescheid? Hat er nach seiner Tochter gefragt?","Hat er etwas gegessen oder getrunken?","Danke, Hilde, für diese Nacht."],
bv20:["Guten Morgen, Frau Brandt. Schön, dass Sie da sind.","Was führt Sie heute zu uns?","Seit wann wird es schlechter?","Was macht es besser, was macht es schlimmer?","Sind Ihre Beine geschwollen?","Haben Sie zugenommen? Wie viel?","Hatten Sie so etwas schon einmal?","Das stimmt. Danke, dass Sie mir das sagen.","Jetzt habe ich noch einige Fragen zu Ihren Tabletten.","Welche Medikamente nehmen Sie? Haben Sie alle jeden Tag genommen, oder haben Sie etwas vergessen?","Haben Sie Vorerkrankungen? Haben Sie Allergien?","Rauchen Sie?","Ich sehe, dass Sie sich Sorgen machen.","Was macht Ihnen am meisten Sorgen?","Gehen Sie am Donnerstag wieder zu Ihrem Kurs?","Ich vermute, dass Ihr Herz wieder zu schwach pumpt und sich Wasser in der Lunge und in den Beinen sammelt.","@ Ihr Herz pumpt zu schwach, deshalb sammelt sich Wasser in der Lunge und in den Beinen.","Wir werden Blut abnehmen und ein EKG schreiben.","Zu Hause wiegen Sie sich bitte jeden Morgen, und die Wassertablette nehmen Sie jeden Tag mittags.","Können Sie mir bitte in Ihren eigenen Worten sagen, was Sie zu Hause machen?","@ Erstens: jeden Morgen wiegen und bei zwei Kilo mehr anrufen. Zweitens: die Wassertablette jeden Tag mittags nehmen. Drittens: kein Ibuprofen und weniger Salz.","Darf ich kurz zusammenfassen? Seit drei Tagen bekommen Sie schlechter Luft. Stimmt das so?","Ich sehe, dass Ihnen die Treppe schwerfällt. Möchten Sie Hilfe zu Hause, zum Beispiel eine Haushaltshilfe?","@ Ja, ich komme morgen früh nach der Übergabe und schaue nach Ihnen.","Haben Sie noch Fragen?"]
};

