// BOSX taunts (s2/s3) tied to error tags (I5 D14); keyed by the first 14 characters of the German line. Missing = any tag.
const BOSS2_TAUNT_TAGS={
 "Knusper, knusp":["genus"],"Ich sehe dich ":["genus"],"Das Glas bleib":["genus","akk","nom","kein","dat"],
 "Das Verb steht":["v2","klammer","trennbar","perfekt","neben"],
 "Du wärst zufri":["konj2"],"Es wurde geler":["passiv"],"Ich verneine d":["praet","perf","indirekt"],
 "Die Wände neig":["konn","neben"],"Nominalstil, m":["nominal","koll"],"Sie „bekommen“":["ff"],"Eventuell best":["ff"]};

// ---------------------------------------------------------------- items (I5 P2–P5, a:0 = right answer first; shuffled at display time)
// Hexe noun table: [genus, noun, plural ("" = none in use), English, why-gender, why-plural] → c_i7 builds a seal item and a plural item from each row
BOSS2.hexe.nouns=[
["der","Tisch","Tische","table","No ending rule. Learn it with its seal: der Tisch.","Most one-syllable der-nouns add -e: Tische."],
["die","Lampe","Lampen","lamp","Nouns ending in -e are mostly die.","Nouns in -e add -n: Lampen."],
["das","Mädchen","Mädchen","girl","-chen is always das, even for a girl.","-chen never changes in the plural."],
["die","Zeitung","Zeitungen","newspaper","-ung is always die.","-ung adds -en: Zeitungen."],
["der","Montag","Montage","Monday","Days, months and seasons are der.","-e: Montage."],
["das","Kind","Kinder","child","No rule. das Kind.","Short das-nouns often add -er: Kinder."],
["die","Krankheit","Krankheiten","illness","-heit and -keit are always die.","-heit adds -en: Krankheiten."],
["der","Arzt","Ärzte","doctor (man)","A male person is der.","Umlaut + -e: Ärzte."],
["die","Ärztin","Ärztinnen","doctor (woman)","-in for a woman is always die.","-in doubles the n: Ärztinnen."],
["das","Fieber","","fever","No rule; -er is often der, but it is das Fieber.",""],
["der","Kaffee","","coffee","Most drinks are der (not das Bier, das Wasser, die Milch).",""],
["das","Brötchen","Brötchen","bread roll","-chen is always das.","-chen never changes."],
["die","Tablette","Tabletten","tablet","-e is mostly die.","-e adds -n: Tabletten."],
["der","Löffel","Löffel","spoon","-el is often der.","der-nouns in -el, -er, -en add nothing: Löffel."],
["das","Messer","Messer","knife","Exception: -er is often der, but das Messer.","-er adds nothing: Messer."],
["die","Gabel","Gabeln","fork","Exception: -el is often der, but die Gabel.","die-nouns in -el add -n: Gabeln."],
["das","Wasser","","water","das Wasser. One of the drinks that is not der.",""],
["der","Apfel","Äpfel","apple","-el is often der.","Only the Umlaut changes: Äpfel."],
["die","Nacht","Nächte","night","No rule. die Nacht (but der Tag, der Abend).","Umlaut + -e: Nächte."],
["das","Auto","Autos","car","Foreign words in -o are mostly das.","Foreign words in a vowel add -s: Autos."],
["der","Kopf","Köpfe","head","No rule. der Kopf.","Umlaut + -e: Köpfe."],
["die","Hand","Hände","hand","No rule. die Hand.","Umlaut + -e: Hände."],
["das","Herz","Herzen","heart","No rule. das Herz.","-en: Herzen."],
["die","Apotheke","Apotheken","pharmacy","-e is mostly die.","-e adds -n: Apotheken."],
["der","Wald","Wälder","forest","No rule. der Wald.","Umlaut + -er: Wälder."],
["das","Haus","Häuser","house","No rule. das Haus.","Umlaut + -er: Häuser."],
["die","Hexe","Hexen","witch","-e is mostly die. She is feminine. She insists.","-e adds -n: Hexen."],
["der","Ofen","Öfen","oven","-en is often der.","Only the Umlaut changes: Öfen."],
["das","Rezept","Rezepte","recipe; prescription","No rule. das Rezept.","-e: Rezepte."],
["die","Untersuchung","Untersuchungen","examination","-ung is always die.","-ung adds -en."],
["der","Schlüssel","Schlüssel","key","-el is often der.","No change: Schlüssel."],
["die","Tür","Türen","door","No rule. die Tür.","-en: Türen."],
["das","Buch","Bücher","book","No rule. das Buch.","Umlaut + -er: Bücher."],
["der","Baum","Bäume","tree","Trees as a word: der Baum.","Umlaut + -e: Bäume."],
["die","Katze","Katzen","cat","-e is mostly die.","-e adds -n: Katzen."],
["das","Bett","Betten","bed","No rule. das Bett.","-en: Betten."],
["der","Tag","Tage","day","Days and times of day are der (not die Nacht).","-e, no Umlaut: Tage."],
["die","Wohnung","Wohnungen","flat","-ung is always die.","-ung adds -en."],
["das","Zimmer","Zimmer","room","Exception: -er is often der, but das Zimmer.","-er adds nothing: Zimmer."],
["der","Patient","Patienten","patient (man)","A male person is der.","-en: Patienten."],
["die","Schwester","Schwestern","sister; nurse","A female person is die.","die-nouns in -er add -n: Schwestern."],
["das","Krankenhaus","Krankenhäuser","hospital","The last part decides: das Haus → das Krankenhaus.","Like Haus: Krankenhäuser."]];
BOSS2.hexe.items=[
// ---- phase 2 · Das Rezept (nominative, accusative, kein)
{ph:2,tag:"akk",type:"mc",q:"Ich nehme ___ Löffel.",o:["den","der","dem"],a:0,why:"nehmen needs the accusative. der Löffel → den Löffel."},
{ph:2,tag:"nom",type:"mc",q:"___ Ofen ist heiß.",o:["Der","Den","Das"],a:0,why:"The oven is the subject: nominative, der Ofen."},
{ph:2,tag:"akk",type:"mc",q:"Die Hexe hat ___ Katze.",o:["eine","einen","ein"],a:0,why:"die Katze: feminine does not change in the accusative. eine Katze."},
{ph:2,tag:"akk",type:"mc",q:"Sie braucht ___ Apfel.",o:["einen","ein","eine"],a:0,why:"der Apfel, accusative → einen Apfel. Only the masculine changes."},
{ph:2,tag:"akk",type:"mc",q:"Ich sehe ___ Haus aus Lebkuchen.",o:["das","den","die"],a:0,why:"das Haus: neuter does not change in the accusative."},
{ph:2,tag:"nom",type:"mc",q:"___ Kind isst das Brot.",o:["Das","Den","Der"],a:0,why:"Who eats? The child: subject, nominative, das Kind."},
{ph:2,tag:"akk",type:"mc",q:"Sie kocht ___ Suppe.",o:["die","der","den"],a:0,why:"die Suppe stays die in the accusative."},
{ph:2,tag:"kein",type:"mc",q:"Ich habe ___ Hunger.",o:["keinen","kein","keine"],a:0,why:"der Hunger, accusative → keinen Hunger."},
{ph:2,tag:"nom",type:"mc",q:"Das ist ___ Messer.",o:["ein","einen","eine"],a:0,why:"After sein the noun stays in the nominative: das Messer → ein Messer."},
{ph:2,tag:"nom",type:"mc",q:"Das ist ___ Arzt.",o:["der","den","dem"],a:0,why:"After sein there is no accusative. Das ist der Arzt."},
{ph:2,tag:"akk",type:"mc",q:"Die Hexe sucht ___ Schlüssel.",o:["den","der","das"],a:0,why:"suchen needs the accusative. der Schlüssel → den Schlüssel."},
{ph:2,tag:"akk",type:"mc",q:"Das Kind öffnet ___ Tür.",o:["die","den","das"],a:0,why:"die Tür stays die in the accusative."},
{ph:2,tag:"akk",type:"mc",q:"Wir trinken ___ Wasser.",o:["das","den","die"],a:0,why:"das Wasser: neuter does not change."},
{ph:2,tag:"kein",type:"mc",q:"Sie hat ___ Zeit.",o:["keine","keinen","kein"],a:0,why:"die Zeit → keine Zeit."},
{ph:2,tag:"akk",type:"mc",q:"Ich brauche ___ Rezept.",o:["ein","einen","eine"],a:0,why:"das Rezept → ein Rezept, also in the accusative."},
{ph:2,tag:"nom",type:"mc",q:"___ Patientin hat Fieber.",o:["Die","Der","Den"],a:0,why:"-in is always die; she is the subject."},
{ph:2,tag:"akk",type:"mc",q:"Der Arzt untersucht ___ Mann.",o:["den","der","die"],a:0,why:"The man is examined: accusative, den Mann. The doctor is the subject: der Arzt."},
{ph:2,tag:"akk",type:"mc",q:"Ich kaufe ___ Kaffee.",o:["einen","ein","eine"],a:0,why:"der Kaffee, accusative → einen Kaffee."},
{ph:2,tag:"nom",type:"mc",q:"Wo ist ___ Löffel?",o:["der","den","dem"],a:0,why:"In a question with sein the noun is still the subject: der Löffel."},
{ph:2,tag:"akk",type:"mc",q:"Sie isst ___ Kuchen nicht.",o:["den","der","dem"],a:0,why:"essen needs the accusative. der Kuchen → den Kuchen."},
{ph:2,tag:"akk",type:"mc",q:"Das Mädchen hat ___ Bruder.",o:["einen","ein","eine"],a:0,why:"der Bruder, accusative after haben → einen Bruder."},
{ph:2,tag:"akk",type:"mc",q:"Ich kenne ___ Frau nicht.",o:["die","der","den"],a:0,why:"die Frau stays die in the accusative."},
{ph:2,tag:"kein",type:"mc",q:"Der Wald hat ___ Ende.",o:["kein","keinen","keine"],a:0,why:"das Ende → kein Ende."},
{ph:2,tag:"nom",type:"mc",q:"Wer ist ___ Mann dort?",o:["der","den","einen"],a:0,why:"With sein: nominative. Wer ist der Mann?"},
{ph:2,tag:"akk",type:"gap",q:"Ich sehe ___ Ofen. (the)",a:"den",alt:[],why:"der Ofen, accusative after sehen → den Ofen."},
{ph:2,tag:"akk",type:"gap",q:"Sie hat ___ Katze. (a)",a:"eine",alt:[],why:"die Katze → eine Katze."},
{ph:2,tag:"kein",type:"gap",q:"Das ist ___ Problem. (no)",a:"kein",alt:[],why:"das Problem → kein Problem."},
{ph:2,tag:"akk",type:"gap",q:"Er nimmt ___ Tablette. (the)",a:"die",alt:[],why:"die Tablette stays die."},
// ---- phase 2, only when lesson g5 is known (practice from realm II, hard modes)
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Sie gibt ___ Kind einen Apfel.",o:["dem","das","den"],a:0,why:"Who gets it? Dative. das Kind → dem Kind."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Sie kocht mit ___ Löffel.",o:["dem","den","der"],a:0,why:"mit always takes the dative. der Löffel → dem Löffel."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Ich helfe ___ Hexe nicht.",o:["der","die","den"],a:0,why:"helfen takes the dative. die Hexe → der Hexe."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Das Haus gehört ___ Frau.",o:["der","die","den"],a:0,why:"gehören takes the dative. die Frau → der Frau."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Sie gibt ___ Mann das Rezept.",o:["dem","den","der"],a:0,why:"The receiver is dative: dem Mann. The thing is accusative: das Rezept."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Nach ___ Essen schläft sie.",o:["dem","das","den"],a:0,why:"nach always takes the dative. das Essen → dem Essen."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Er kommt aus ___ Wald.",o:["dem","den","der"],a:0,why:"aus always takes the dative. der Wald → dem Wald."},
{ph:2,tag:"dat",need:"g5",type:"mc",q:"Ich danke ___ Ärztin.",o:["der","die","den"],a:0,why:"danken takes the dative. die Ärztin → der Ärztin."},
// ---- phase 3 · Der Ofen (plural in a sentence; the noun rows above add 39 more)
{ph:3,tag:"plural",type:"mc",q:"Die ___ sind heiß.",o:["Öfen","Ofen","Ofens"],a:0,why:"der Ofen → die Öfen: only the Umlaut changes."},
{ph:3,tag:"plural",type:"mc",q:"Die Hexe hat zwei ___.",o:["Katzen","Katze","Katzes"],a:0,why:"Nouns in -e add -n: die Katzen."},
{ph:3,tag:"plural",type:"mc",q:"Im Wald stehen viele ___.",o:["Bäume","Baume","Baums"],a:0,why:"der Baum → die Bäume: Umlaut + -e."},
{ph:3,tag:"plural",type:"mc",q:"In the plural the article of every noun is ___.",o:["die","der","das"],a:0,why:"der Tisch, die Lampe, das Kind — die Tische, die Lampen, die Kinder."},
{ph:3,tag:"plural",type:"mc",q:"Ich lese drei ___.",o:["Bücher","Buchen","Buchs"],a:0,why:"das Buch → die Bücher: Umlaut + -er."},
{ph:3,tag:"plural",type:"mc",q:"Der Arzt hat heute zwanzig ___.",o:["Patienten","Patiente","Patients"],a:0,why:"der Patient → die Patienten."},
{ph:3,tag:"plural",type:"mc",q:"Die ___ sind offen.",o:["Türen","Türe","Türs"],a:0,why:"die Tür → die Türen."},
{ph:3,tag:"plural",type:"mc",q:"Sie nimmt drei ___ am Tag.",o:["Tabletten","Tablette","Tablettes"],a:0,why:"die Tablette → die Tabletten."},
{ph:3,tag:"plural",type:"fix",q:"Die Hexe hat zwei Kinds im Käfig.",a:"Die Hexe hat zwei Kinder im Käfig.",err:"Kinds",why:"das Kind → die Kinder. German almost never makes the plural with -s."},
{ph:3,tag:"plural",type:"fix",q:"Im Haus sind vier Zimmers.",a:"Im Haus sind vier Zimmer.",err:"Zimmers",why:"das Zimmer → die Zimmer: nouns in -er add nothing."},
{ph:3,tag:"plural",type:"fix",q:"Ich habe zwei Hands.",a:"Ich habe zwei Hände.",err:"Hands",why:"die Hand → die Hände: Umlaut + -e."},
{ph:3,tag:"plural",type:"fix",q:"Die Ärzten sind im Krankenhaus.",a:"Die Ärzte sind im Krankenhaus.",err:"Ärzten",why:"der Arzt → die Ärzte. (Ärzten is only the dative plural.)"}];
BOSS2.golem.items=[
// ---- phase 1 · Lehm: verb second
{ph:1,tag:"v2",type:"order",words:["Heute","arbeite","ich","im","Krankenhaus","."],a:"Heute arbeite ich im Krankenhaus.",why:"Time first — the verb stays second, the subject moves behind it."},
{ph:1,tag:"v2",type:"order",words:["Der","Golem","steht","im","Café","."],a:"Der Golem steht im Café.",why:"Subject, verb, rest: the verb is the second element."},
{ph:1,tag:"v2",type:"order",words:["Morgen","kommt","die","Ärztin","um","acht","."],a:"Morgen kommt die Ärztin um acht.",alt:["Morgen kommt um acht die Ärztin."],why:"Morgen is element one, so kommt follows at once."},
{ph:1,tag:"v2",type:"order",words:["Wo","haben","Sie","Schmerzen","?"],a:"Wo haben Sie Schmerzen?",why:"Question word, verb, subject."},
{ph:1,tag:"v2",type:"order",words:["Jetzt","braucht","der","Patient","Ruhe","."],a:"Jetzt braucht der Patient Ruhe.",why:"Jetzt takes place one; braucht keeps place two."},
{ph:1,tag:"v2",type:"order",words:["Seit","gestern","habe","ich","Fieber","."],a:"Seit gestern habe ich Fieber.",why:"Seit gestern is one element. Then the verb."},
{ph:1,tag:"v2",type:"order",words:["Am","Montag","beginnt","mein","Dienst","."],a:"Am Montag beginnt mein Dienst.",why:"Am Montag is one element; beginnt is second."},
{ph:1,tag:"v2",type:"order",words:["Wann","beginnt","die","Visite","?"],a:"Wann beginnt die Visite?",why:"Question word, then the verb."},
{ph:1,tag:"v2",type:"order",words:["In","Prag","trinkt","man","viel","Kaffee","."],a:"In Prag trinkt man viel Kaffee.",why:"Place first, verb second, man third."},
{ph:1,tag:"v2",type:"order",words:["Vielleicht","schläft","der","Golem","."],a:"Vielleicht schläft der Golem.",why:"Vielleicht counts as element one."},
{ph:1,tag:"v2",type:"order",words:["Dem","Patienten","geht","es","besser","."],a:"Dem Patienten geht es besser.",why:"Even a dative can stand first. The verb does not care: place two."},
{ph:1,tag:"v2",type:"order",words:["Trinken","Sie","genug","Wasser","?"],a:"Trinken Sie genug Wasser?",why:"Yes/no question: the verb is first."},
{ph:1,tag:"v2",type:"order",words:["Danach","gehen","wir","ins","Labor","."],a:"Danach gehen wir ins Labor.",why:"Danach first, verb second."},
{ph:1,tag:"v2",type:"order",words:["Leider","habe","ich","keine","Zeit","."],a:"Leider habe ich keine Zeit.",why:"Leider first, verb second, subject third."},
{ph:1,tag:"v2",type:"fix",q:"Heute ich habe Dienst.",a:"Heute habe ich Dienst.",err:"ich habe",why:"Two things before the verb is one too many. Heute habe ich …"},
{ph:1,tag:"v2",type:"fix",q:"Wo Sie arbeiten?",a:"Wo arbeiten Sie?",err:"Sie arbeiten",why:"After the question word comes the verb."},
// ---- phase 2 · Die Klammer: modal, separable verb, perfect
{ph:2,tag:"klammer",type:"order",words:["Ich","muss","den","Patienten","untersuchen","."],a:"Ich muss den Patienten untersuchen.",why:"Modal verb second, infinitive last: the bracket."},
{ph:2,tag:"klammer",type:"order",words:["Sie","dürfen","hier","nicht","rauchen","."],a:"Sie dürfen hier nicht rauchen.",why:"dürfen second, rauchen last; nicht stands before the last part."},
{ph:2,tag:"trennbar",type:"order",words:["Ich","rufe","Sie","morgen","an","."],a:"Ich rufe Sie morgen an.",why:"anrufen splits: rufe second, an last."},
{ph:2,tag:"trennbar",type:"order",words:["Der","Golem","steht","jeden","Abend","auf","."],a:"Der Golem steht jeden Abend auf.",why:"aufstehen splits: the prefix closes the sentence."},
{ph:2,tag:"perfekt",type:"order",words:["Ich","habe","den","Befund","gelesen","."],a:"Ich habe den Befund gelesen.",why:"Perfect: haben second, participle last."},
{ph:2,tag:"perfekt",type:"order",words:["Wir","sind","gestern","nach","Prag","gefahren","."],a:"Wir sind gestern nach Prag gefahren.",why:"Movement takes sein; gefahren closes the bracket. Time before place."},
{ph:2,tag:"klammer",type:"order",words:["Können","Sie","den","Arm","heben","?"],a:"Können Sie den Arm heben?",why:"Question: modal first, infinitive still last."},
{ph:2,tag:"trennbar",type:"order",words:["Machen","Sie","bitte","den","Mund","auf","!"],a:"Machen Sie bitte den Mund auf!",alt:["Machen Sie den Mund bitte auf!"],why:"Imperative of aufmachen: verb first, auf last."},
{ph:2,tag:"perfekt",type:"order",words:["Der","Patient","ist","um","drei","aufgewacht","."],a:"Der Patient ist um drei aufgewacht.",why:"aufwachen is a change of state: sein. Participle last."},
{ph:2,tag:"perfekt",type:"order",words:["Ich","habe","mir","die","Hände","gewaschen","."],a:"Ich habe mir die Hände gewaschen.",why:"mir comes right after the verb; gewaschen last."},
{ph:2,tag:"klammer",type:"order",words:["Sie","soll","die","Tablette","morgens","nehmen","."],a:"Sie soll die Tablette morgens nehmen.",alt:["Sie soll morgens die Tablette nehmen."],why:"soll second, nehmen last."},
{ph:2,tag:"perfekt",type:"order",words:["Wann","sind","Sie","aufgestanden","?"],a:"Wann sind Sie aufgestanden?",why:"Question word, sind, subject, participle."},
{ph:2,tag:"klammer",type:"order",words:["Ich","möchte","mich","kurz","vorstellen","."],a:"Ich möchte mich kurz vorstellen.",why:"möchte second; after a modal the separable verb stays together at the end."},
{ph:2,tag:"perfekt",type:"order",words:["Er","hat","gestern","nichts","gegessen","."],a:"Er hat gestern nichts gegessen.",why:"hat second, gegessen last; nichts stands before the participle."},
{ph:2,tag:"perfekt",type:"mc",q:"Ich ___ den Patienten heute ___.",o:["habe … untersucht","habe untersucht …","untersucht … habe"],a:0,why:"The two verb parts stand at the two ends: habe (2) … untersucht (last)."},
{ph:2,tag:"klammer",type:"mc",q:"Welcher Satz ist richtig?",o:["Ich kann heute nicht kommen.","Ich kann kommen heute nicht.","Ich heute kann nicht kommen."],a:0,why:"kann second, kommen last, everything else inside the bracket."},
{ph:2,tag:"perfekt",type:"fix",q:"Ich habe gegessen nichts.",a:"Ich habe nichts gegessen.",err:"gegessen nichts",why:"The participle is the last brick."},
{ph:2,tag:"trennbar",type:"fix",q:"Ich aufstehe um sechs Uhr.",a:"Ich stehe um sechs Uhr auf.",err:"aufstehe",alt:["Um sechs Uhr stehe ich auf."],why:"In a main clause the prefix goes to the end: stehe … auf."},
// ---- phase 3 · Der Nebensatz: verb last; after a subordinate clause, verb first
{ph:3,tag:"neben",type:"order",pre:"Ich bleibe zu Hause,",words:["weil","ich","krank","bin","."],a:"weil ich krank bin.",why:"weil sends the verb to the end."},
{ph:3,tag:"neben",type:"order",pre:"Der Patient sagt,",words:["dass","er","Schmerzen","hat","."],a:"dass er Schmerzen hat.",why:"dass sends the verb to the end."},
{ph:3,tag:"neben",type:"order",pre:"Ich weiß nicht,",words:["ob","der","Arzt","heute","kommt","."],a:"ob der Arzt heute kommt.",why:"ob = whether; the verb is last."},
{ph:3,tag:"neben",type:"order",pre:"Rufen Sie an,",words:["wenn","Sie","Fieber","bekommen","."],a:"wenn Sie Fieber bekommen.",why:"wenn sends the verb to the end."},
{ph:3,tag:"neben",type:"order",pre:"Er kommt nicht,",words:["weil","er","arbeiten","muss","."],a:"weil er arbeiten muss.",why:"With a modal: infinitive, then the modal as the very last word."},
{ph:3,tag:"neben",type:"order",pre:"Sie sagt,",words:["dass","sie","die","Tablette","genommen","hat","."],a:"dass sie die Tablette genommen hat.",why:"Perfect in a subordinate clause: participle, then hat at the very end."},
{ph:3,tag:"neben",type:"order",pre:"Ich frage,",words:["ob","Sie","mich","verstehen","."],a:"ob Sie mich verstehen.",why:"ob … verb last."},
{ph:3,tag:"neben",type:"order",pre:"Der Golem bleibt stehen,",words:["wenn","der","Satz","richtig","ist","."],a:"wenn der Satz richtig ist.",why:"wenn … ist: verb last."},
{ph:3,tag:"neben",type:"order",pre:"Ich glaube,",words:["dass","er","heute","aufsteht","."],a:"dass er heute aufsteht.",why:"At the end of a subordinate clause the separable verb is one word again: aufsteht."},
{ph:3,tag:"neben",type:"order",pre:"Sie ist müde,",words:["weil","sie","nicht","geschlafen","hat","."],a:"weil sie nicht geschlafen hat.",why:"nicht, participle, hat."},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Wenn ich Zeit habe,",words:["komme","ich","morgen","."],a:"komme ich morgen.",why:"The whole wenn-clause is element one. So the verb comes right after the comma."},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Weil der Golem wächst,",words:["müssen","wir","schnell","sein","."],a:"müssen wir schnell sein.",why:"Clause first, then verb, then subject: …, müssen wir …"},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Wenn Sie Schmerzen haben,",words:["nehmen","Sie","eine","Tablette","."],a:"nehmen Sie eine Tablette.",why:"After the comma: verb first."},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Weil ich Dienst hatte,",words:["habe","ich","nicht","geschlafen","."],a:"habe ich nicht geschlafen.",why:"Verb after the comma, participle at the end."},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Dass er krank ist,",words:["weiß","ich","schon","."],a:"weiß ich schon.",why:"A dass-clause can stand first too. Then: verb, subject."},
{ph:3,tag:"neben",act:"mauer",type:"order",pre:"Ob sie heute kommt,",words:["wissen","wir","nicht","."],a:"wissen wir nicht.",why:"Clause first, verb second in the whole sentence."},
{ph:3,tag:"neben",type:"mc",q:"Ich komme nicht, weil ich ___.",o:["krank bin","bin krank","krank ich bin"],a:0,why:"weil: the verb is the last word."},
{ph:3,tag:"neben",type:"mc",q:"Wenn es regnet, ___ zu Hause.",o:["bleibe ich","ich bleibe","ich bleiben"],a:0,why:"After a clause in first place the verb follows directly."},
{ph:3,tag:"neben",type:"fix",q:"Er sagt, dass er hat Fieber.",a:"Er sagt, dass er Fieber hat.",err:"hat Fieber",why:"dass: verb to the end."},
{ph:3,tag:"neben",type:"transform",q:"Verbinden Sie mit „weil“: Ich trinke Tee. Ich bin krank.",a:"Ich trinke Tee, weil ich krank bin.",alt:["Weil ich krank bin, trinke ich Tee."],x:["denn","ist"],why:"weil + verb at the end. Or the weil-clause first, then trinke ich."},
// ---- finisher · the last letter of ANFÄNGER: exactly one wrong word in each paragraph
{ph:4,tag:"perfekt",type:"spot",text:"Gestern bin ich nach Prag gefahren. Im Café habe ich einen Kaffee bestellt. Der Kellner hat mir den Kaffee gebracht. Dann habe ich mit dem Golem gesprochen. Er hat mich nicht verstehen.",err:"verstehen",a:"verstanden",why:"Perfect needs the participle: hat … verstanden."},
{ph:4,tag:"kasus",type:"spot",text:"Der Mann kommt aus Prag. Er hat seit drei Tagen Husten. Ich gebe den Mann eine Tablette. Er nimmt sie mit Wasser. Morgen kommt er wieder.",err:"den Mann",a:"dem Mann",why:"geben: the receiver is dative. dem Mann."},
{ph:4,tag:"kasus",type:"spot",text:"Ich stehe jeden Tag um sechs Uhr auf. Dann fahre ich mit der Bus ins Krankenhaus. Dort arbeite ich bis vier. Am Abend lerne ich Deutsch.",err:"der Bus",a:"dem Bus",why:"mit always takes the dative: der Bus → mit dem Bus."},
{ph:4,tag:"kasus",type:"spot",text:"Der Golem steht in der Küche. Er stellt den Stuhl auf dem Tisch. Dann geht er in den Keller. Im Keller ist es dunkel.",err:"dem Tisch",a:"den Tisch",why:"stellen is movement to a place (wohin?): accusative, auf den Tisch."},
{ph:4,tag:"perfekt",type:"spot",text:"Frau Novák kann heute nicht kommen, weil sie krank ist. Sie hat den Arzt angerufen. Der Arzt hat ihr gesagt, dass sie im Bett bleiben muss. Am Abend hat sie viel Tee getrinkt.",err:"getrinkt",a:"getrunken",why:"trinken is a strong verb: trinken, trank, getrunken."},
{ph:4,tag:"kasus",type:"spot",text:"Wir möchten uns vorstellen. Ich heiße Jana und das ist mein Kollege. Wir arbeiten seit einem Jahr in dieses Krankenhaus. Die Arbeit gefällt uns gut.",err:"dieses",a:"diesem",why:"wo? in + dative: in diesem Krankenhaus."},
{ph:4,tag:"kasus",type:"spot",text:"Können Sie mir helfen? Ich suche die Apotheke. Gehen Sie hier geradeaus und dann links. Die Apotheke ist neben die Bank.",err:"die Bank",a:"der Bank",why:"wo? neben + dative: die Bank → neben der Bank."},
{ph:4,tag:"perfekt",type:"spot",text:"Gestern hatte ich Dienst. Ich wollte um acht nach Hause gehen, aber ich musste bleiben. Ein Patient konnte nicht atmen. Wir haben ihn sofort untersuchen.",err:"untersuchen",a:"untersucht",why:"haben + participle: untersucht (no ge-, the verb is inseparable)."},
{ph:4,tag:"neben",type:"spot",text:"Der Patient bleibt heute hier. Er kann nicht nach Hause gehen, weil er hat hohes Fieber. Morgen untersuchen wir ihn noch einmal. Dann rufen wir seine Frau an.",err:"hat hohes Fieber",a:"hohes Fieber hat",why:"weil sends the verb to the end: weil er hohes Fieber hat."},
{ph:4,tag:"v2",type:"spot",text:"Um sieben Uhr beginnt die Visite. Zuerst wir sehen den Patienten in Zimmer drei. Er hat gut geschlafen. Danach gehen wir zu Frau Novák.",err:"wir sehen",a:"sehen wir",why:"Zuerst is in first place, so the verb comes second: Zuerst sehen wir …"}];
// 12 chains × 4 shapes + 4 Nebel items. q repeats the base sentence so every item is complete on its own. x = extra distractor tiles.
BOSS2.pudel.items=[
// c1
{chain:"c1",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Arzt untersucht den Patienten.",a:"Der Arzt untersuchte den Patienten.",alt:[],x:["untersucht","hat"],why:"Schwaches Verb: Stamm + -te. untersuchte."},
{chain:"c1",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Arzt untersucht den Patienten.",a:"Der Arzt hat den Patienten untersucht.",alt:[],x:["ist","geuntersucht"],why:"haben + Partizip; untersuchen ist untrennbar, also ohne ge-."},
{chain:"c1",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Arzt untersucht den Patienten.",a:"Der Patient wird vom Arzt untersucht.",alt:["Der Patient wird untersucht.","Der Patient wird von dem Arzt untersucht."],x:["den","worden"],why:"Das Akkusativobjekt wird Subjekt: der Patient. werden + Partizip II."},
{chain:"c1",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Der Arzt sagt: „Ich untersuche den Patienten.“",a:"Der Arzt sagt, er untersuche den Patienten.",alt:["Der Arzt sagt, dass er den Patienten untersuche.","Der Arzt sagt, dass er den Patienten untersucht."],x:["ich","untersucht"],why:"ich → er; Konjunktiv I: er untersuche (Stamm + -e)."},
// c2
{chain:"c2",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Faust schreibt einen Brief.",a:"Faust schrieb einen Brief.",alt:[],x:["schreibte","geschrieben"],why:"Starkes Verb: schreiben, schrieb, geschrieben. Keine Endung in der 3. Person."},
{chain:"c2",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Faust schreibt einen Brief.",a:"Faust hat einen Brief geschrieben.",alt:[],x:["ist","geschreibt"],why:"haben + geschrieben."},
{chain:"c2",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Faust schreibt einen Brief.",a:"Ein Brief wird von Faust geschrieben.",alt:["Ein Brief wird geschrieben."],x:["einen","schrieb"],why:"einen Brief → ein Brief (Nominativ). wird … geschrieben."},
{chain:"c2",shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Irreal: Faust hat keine Tinte. Er schreibt keinen Brief. → Wenn Faust Tinte …",a:"Wenn Faust Tinte hätte, würde er einen Brief schreiben.",alt:["Wenn Faust Tinte hätte, schriebe er einen Brief."],x:["hat","wird"],why:"Irreale Bedingung: hätte im wenn-Satz, würde + Infinitiv im Hauptsatz."},
// c3
{chain:"c3",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Die Schwester gibt dem Patienten das Medikament.",a:"Die Schwester gab dem Patienten das Medikament.",alt:[],x:["gebte","gegeben"],why:"geben, gab, gegeben."},
{chain:"c3",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Die Schwester gibt dem Patienten das Medikament.",a:"Die Schwester hat dem Patienten das Medikament gegeben.",alt:[],x:["ist","gegebt"],why:"haben + gegeben; Dativ vor Akkusativ bleibt."},
{chain:"c3",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Die Schwester gibt dem Patienten das Medikament.",a:"Das Medikament wird dem Patienten gegeben.",alt:["Dem Patienten wird das Medikament gegeben.","Das Medikament wird dem Patienten von der Schwester gegeben.","Dem Patienten wird das Medikament von der Schwester gegeben."],x:["der","den"],why:"Nur der Akkusativ wird Subjekt. Der Dativ bleibt Dativ: dem Patienten."},
{chain:"c3",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Die Schwester sagt: „Ich gebe dem Patienten das Medikament.“",a:"Die Schwester sagt, sie gebe dem Patienten das Medikament.",alt:["Die Schwester sagt, dass sie dem Patienten das Medikament gebe.","Die Schwester sagt, dass sie dem Patienten das Medikament gibt."],x:["ich","gibt"],why:"ich → sie; Konjunktiv I ohne Vokalwechsel: sie gebe (nicht gibt)."},
// c4
{chain:"c4",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Pudel nimmt das Buch.",a:"Der Pudel nahm das Buch.",alt:[],x:["nehmte","genommen"],why:"nehmen, nahm, genommen."},
{chain:"c4",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Pudel nimmt das Buch.",a:"Der Pudel hat das Buch genommen.",alt:[],x:["ist","genehmt"],why:"haben + genommen."},
{chain:"c4",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Pudel nimmt das Buch.",a:"Das Buch wird vom Pudel genommen.",alt:["Das Buch wird genommen.","Das Buch wird von dem Pudel genommen."],x:["nahm","worden"],why:"das Buch bleibt das Buch; wird … genommen."},
{chain:"c4",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Mephisto sagt: „Der Pudel nimmt das Buch.“",a:"Mephisto sagt, der Pudel nehme das Buch.",alt:["Mephisto sagt, dass der Pudel das Buch nehme.","Mephisto sagt, dass der Pudel das Buch nimmt."],x:["nimmt","nähme"],why:"Konjunktiv I: er nehme. Kein Vokalwechsel, Endung -e."},
// c5
{chain:"c5",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Wir operieren die Patientin morgens.",a:"Wir operierten die Patientin morgens.",alt:[],x:["operiert","haben"],why:"Schwach: operier- + -ten."},
{chain:"c5",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Wir operieren die Patientin morgens.",a:"Wir haben die Patientin morgens operiert.",alt:[],x:["sind","geoperiert"],why:"Verben auf -ieren: Partizip ohne ge-. operiert."},
{chain:"c5",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Wir operieren die Patientin morgens.",a:"Die Patientin wird morgens operiert.",alt:["Die Patientin wird morgens von uns operiert."],x:["werden","wir"],why:"wird (Singular: die Patientin) + operiert. „wir“ fällt weg."},
{chain:"c5",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv mit Modalverb: Wir müssen die Patientin morgens operieren.",a:"Die Patientin muss morgens operiert werden.",alt:[],x:["wird","müssen"],why:"Modalverb + Partizip II + werden (Infinitiv am Ende)."},
// c6
{chain:"c6",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Chirurg findet die Ursache.",a:"Der Chirurg fand die Ursache.",alt:[],x:["findete","gefunden"],why:"finden, fand, gefunden."},
{chain:"c6",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Chirurg findet die Ursache.",a:"Der Chirurg hat die Ursache gefunden.",alt:[],x:["ist","gefindet"],why:"haben + gefunden."},
{chain:"c6",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Chirurg findet die Ursache.",a:"Die Ursache wird vom Chirurgen gefunden.",alt:["Die Ursache wird gefunden.","Die Ursache wird von dem Chirurgen gefunden."],x:["Chirurg","fand"],why:"von + Dativ, und der Chirurg ist ein n-Nomen: vom Chirurgen."},
{chain:"c6",shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Irreal: Der Chirurg hat kein CT. Er findet die Ursache nicht. → Wenn der Chirurg ein CT …",a:"Wenn der Chirurg ein CT hätte, würde er die Ursache finden.",alt:["Wenn der Chirurg ein CT hätte, fände er die Ursache."],x:["hat","wird"],why:"hätte … würde finden: Es ist nicht so, nur vorgestellt."},
// c7
{chain:"c7",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Student liest den Befund.",a:"Der Student las den Befund.",alt:[],x:["leste","gelesen"],why:"lesen, las, gelesen."},
{chain:"c7",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Student liest den Befund.",a:"Der Student hat den Befund gelesen.",alt:[],x:["ist","gelest"],why:"haben + gelesen."},
{chain:"c7",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Student liest den Befund.",a:"Der Befund wird vom Studenten gelesen.",alt:["Der Befund wird gelesen.","Der Befund wird von dem Studenten gelesen."],x:["den","las"],why:"den Befund → der Befund; der Student ist ein n-Nomen: vom Studenten."},
{chain:"c7",shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Irreal: Der Student hat keine Zeit. Er liest den Befund nicht. → Wenn der Student Zeit …",a:"Wenn der Student Zeit hätte, würde er den Befund lesen.",alt:["Wenn der Student Zeit hätte, läse er den Befund."],x:["hat","wird"],why:"hätte im wenn-Satz, würde lesen im Hauptsatz."},
// c8
{chain:"c8",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Die Ärztin ruft die Familie an.",a:"Die Ärztin rief die Familie an.",alt:[],x:["anrief","rufte"],why:"rufen, rief, gerufen; trennbar: rief … an."},
{chain:"c8",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Die Ärztin ruft die Familie an.",a:"Die Ärztin hat die Familie angerufen.",alt:[],x:["an","geanruft"],why:"Trennbar: ge- steht in der Mitte. angerufen."},
{chain:"c8",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Die Ärztin ruft die Familie an.",a:"Die Familie wird von der Ärztin angerufen.",alt:["Die Familie wird angerufen."],x:["an","rief"],why:"wird … angerufen; das Partizip ist ein Wort."},
{chain:"c8",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Die Ärztin sagt: „Ich rufe die Familie an.“",a:"Die Ärztin sagt, sie rufe die Familie an.",alt:["Die Ärztin sagt, dass sie die Familie anrufe.","Die Ärztin sagt, dass sie die Familie anruft."],x:["ich","anrufe"],why:"Ohne dass: Hauptsatz-Stellung, rufe … an. Mit dass: anrufe am Ende."},
// c9
{chain:"c9",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Patient vergisst die Tabletten.",a:"Der Patient vergaß die Tabletten.",alt:["Der Patient vergass die Tabletten."],x:["vergesste","vergisst"],why:"vergessen, vergaß, vergessen."},
{chain:"c9",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Patient vergisst die Tabletten.",a:"Der Patient hat die Tabletten vergessen.",alt:[],x:["ist","gevergessen"],why:"Untrennbar (ver-): Partizip ohne ge-. vergessen."},
{chain:"c9",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Patient vergisst die Tabletten.",a:"Die Tabletten werden vom Patienten vergessen.",alt:["Die Tabletten werden vergessen.","Die Tabletten werden von dem Patienten vergessen."],x:["wird","vergaß"],why:"Plural-Subjekt: die Tabletten werden …"},
{chain:"c9",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Der Patient sagt: „Ich habe die Tabletten vergessen.“",a:"Der Patient sagt, er habe die Tabletten vergessen.",alt:["Der Patient sagt, dass er die Tabletten vergessen habe.","Der Patient sagt, dass er die Tabletten vergessen hat."],x:["hat","ich"],why:"Vergangenheit in der indirekten Rede: habe + Partizip."},
// c10
{chain:"c10",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Pfleger bringt den Patienten ins Zimmer.",a:"Der Pfleger brachte den Patienten ins Zimmer.",alt:[],x:["bringte","brang"],why:"Mischverb: bringen, brachte, gebracht."},
{chain:"c10",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Pfleger bringt den Patienten ins Zimmer.",a:"Der Pfleger hat den Patienten ins Zimmer gebracht.",alt:[],x:["ist","gebringt"],why:"haben + gebracht."},
{chain:"c10",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Der Pfleger bringt den Patienten ins Zimmer.",a:"Der Patient wird ins Zimmer gebracht.",alt:["Der Patient wird vom Pfleger ins Zimmer gebracht.","Der Patient wird von dem Pfleger ins Zimmer gebracht."],x:["Patienten","brachte"],why:"den Patienten → der Patient: Im Nominativ fällt das -en weg."},
{chain:"c10",shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Höfliche Bitte (Konjunktiv II von können): Bringen Sie den Patienten ins Zimmer!",a:"Könnten Sie den Patienten bitte ins Zimmer bringen?",alt:["Könnten Sie bitte den Patienten ins Zimmer bringen?","Könnten Sie den Patienten ins Zimmer bringen?"],x:["Können","Bringen"],why:"könnten + Infinitiv am Ende: aus dem Befehl wird eine Bitte."},
// c11 — the trap: an intransitive verb
{chain:"c11",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Der Pudel kommt ins Studierzimmer.",a:"Der Pudel kam ins Studierzimmer.",alt:[],x:["kommte","gekommen"],why:"kommen, kam, gekommen."},
{chain:"c11",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Der Pudel kommt ins Studierzimmer.",a:"Der Pudel ist ins Studierzimmer gekommen.",alt:[],x:["hat","gekommt"],why:"Bewegung von A nach B: sein. ist … gekommen."},
{chain:"c11",shape:"nilpferd",ph:2,tag:"passiv",type:"mc",q:"Passiv: Der Pudel kommt ins Studierzimmer.",o:["Kein Passiv möglich.","Das Studierzimmer wird gekommen.","Der Pudel wird gekommen."],a:0,why:"Ohne Akkusativobjekt gibt es kein Subjekt für das Passiv. kommen hat keins."},
{chain:"c11",shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Wunsch: Der Pudel kommt nicht. → Wenn der Pudel doch …",a:"Wenn der Pudel doch käme!",alt:["Wenn der Pudel doch kommen würde!","Wenn der Pudel doch käme.","Wenn der Pudel doch kommen würde."],x:["kommt","kam"],why:"Irrealer Wunsch: wenn … doch + Konjunktiv II. kam → käme."},
// c12
{chain:"c12",shape:"pudel",ph:1,tag:"praet",type:"transform",q:"Präteritum: Man schließt die Tür um acht.",a:"Man schloss die Tür um acht.",alt:[],x:["schließte","geschlossen"],why:"schließen, schloss, geschlossen."},
{chain:"c12",shape:"nass",ph:1,tag:"perf",type:"transform",q:"Perfekt: Man schließt die Tür um acht.",a:"Man hat die Tür um acht geschlossen.",alt:[],x:["ist","geschließt"],why:"haben + geschlossen."},
{chain:"c12",shape:"nilpferd",ph:2,tag:"passiv",type:"transform",q:"Passiv: Man schließt die Tür um acht.",a:"Die Tür wird um acht geschlossen.",alt:[],x:["man","von"],why:"„man“ verschwindet im Passiv ganz, ohne „von“."},
{chain:"c12",shape:"scholar",ph:3,tag:"indirekt",type:"transform",q:"Indirekte Rede: Der Pförtner sagt: „Man schließt die Tür um acht.“",a:"Der Pförtner sagt, man schließe die Tür um acht.",alt:["Der Pförtner sagt, dass man die Tür um acht schließe.","Der Pförtner sagt, dass man die Tür um acht schließt."],x:["schließt","schlösse"],why:"Konjunktiv I: man schließe."},
// extra Nebel items (phase 3 opener when konj2 is weak)
{shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Höfliche Bitte (Konjunktiv II von werden): Öffnen Sie das Fenster!",a:"Würden Sie bitte das Fenster öffnen?",alt:["Würden Sie das Fenster bitte öffnen?","Würden Sie das Fenster öffnen?"],x:["Werden","Öffnen"],why:"würden + Infinitiv am Ende."},
{shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Höflich (Konjunktiv II von haben): Haben Sie einen Moment Zeit?",a:"Hätten Sie einen Moment Zeit?",alt:[],x:["Haben","Hatten"],why:"haben → hatten → hätten: Umlaut macht den Konjunktiv II."},
{shape:"nebel",ph:3,tag:"konj2",type:"transform",q:"Rat (an meiner Stelle): Sie rauchen. → An Ihrer Stelle …",a:"An Ihrer Stelle würde ich nicht rauchen.",alt:["An Ihrer Stelle würde ich aufhören zu rauchen.","An Ihrer Stelle würde ich nicht mehr rauchen."],x:["werde","Sie"],why:"An Ihrer Stelle + würde ich …: Das Verb steht direkt nach dem ersten Satzteil."},
{shape:"nebel",ph:3,tag:"konj2",type:"mc",q:"Welcher Satz ist irreal?",o:["Wenn ich Zeit hätte, käme ich.","Wenn ich Zeit habe, komme ich.","Wenn ich Zeit hatte, kam ich."],a:0,why:"hätte / käme: Konjunktiv II — ich habe keine Zeit und komme nicht."}];
// phase 1: o[3], where present, is shown only from trance 1. s3 BOSS_X.caligari.falsch (24) is added at load and drawn first.
BOSS2.caligari.items=[
// ---- phase 1 · Cesare schläft: false friends (o[3], where present, is shown from trance 1)
{ph:1,tag:"ff",type:"mc",q:"„Das ist die aktuelle Medikation.“ – Das bedeutet:",o:["die Medikation, die der Patient zurzeit nimmt","die tatsächliche Medikation","die genaue Medikation","die übliche Medikation"],a:0,why:"aktuell = gegenwärtig. ‚actual‘ heißt tatsächlich."},
{ph:1,tag:"ff",type:"mc",q:"„Actually, I feel better.“",o:["Eigentlich geht es mir besser.","Aktuell geht es mir besser.","Eventuell geht es mir besser."],a:0,why:"actually = eigentlich, tatsächlich. ‚Aktuell‘ hieße: im Moment."},
{ph:1,tag:"ff",type:"mc",q:"„Eventuell müssen wir operieren.“ – Das bedeutet:",o:["Vielleicht müssen wir operieren.","Am Ende müssen wir operieren.","Auf jeden Fall müssen wir operieren.","Bald müssen wir operieren."],a:0,why:"eventuell = möglicherweise. ‚eventually‘ heißt schließlich."},
{ph:1,tag:"ff",type:"mc",q:"„The patient became unconscious.“",o:["Der Patient wurde bewusstlos.","Der Patient bekam bewusstlos.","Der Patient bekommt bewusstlos."],a:0,why:"become = werden. bekommen = erhalten."},
{ph:1,tag:"ff",type:"mc",q:"„Die Haut ist sehr sensibel.“ – Das bedeutet:",o:["Die Haut ist empfindlich.","Die Haut ist vernünftig.","Die Haut ist gesund.","Die Haut ist spürbar."],a:0,why:"sensibel = empfindlich, feinfühlig. ‚sensible‘ heißt vernünftig."},
{ph:1,tag:"ff",type:"mc",q:"Der Patient braucht ein Medikament aus der Apotheke. Was stellen Sie aus?",o:["ein Rezept","eine Quittung","eine Rezeption"],a:0,why:"das Rezept = die Verordnung (und das Kochrezept). ‚receipt‘ heißt Quittung."},
{ph:1,tag:"ff",type:"mc",q:"„Das Gift wirkt innerhalb von Minuten.“ – Gemeint ist:",o:["eine giftige Substanz","ein Geschenk","eine Begabung"],a:0,why:"das Gift = poison. ‚gift‘ heißt Geschenk oder Begabung."},
{ph:1,tag:"ff",type:"mc",q:"„Stellen Sie sich bitte morgen in der Ambulanz vor.“ – Wohin soll der Patient?",o:["in die Abteilung für ambulante Behandlung","in den Rettungswagen","auf die Intensivstation","in die Apotheke"],a:0,why:"die Ambulanz = ambulante Abteilung. ‚ambulance‘ heißt Rettungswagen."},
{ph:1,tag:"ff",type:"mc",q:"„She is a physician.“",o:["Sie ist Ärztin.","Sie ist Physikerin.","Sie ist Physiotherapeutin."],a:0,why:"physician = Arzt, Ärztin. Der Physiker ist ‚physicist‘."},
{ph:1,tag:"ff",type:"mc",q:"Welcher Satz ist richtig?",o:["Wir haben die Dosis verdoppelt.","Wir haben die Dose verdoppelt.","Wir haben den Dosis verdoppelt."],a:0,why:"die Dosis = dose. Die Dose ist ein Behälter aus Blech."},
{ph:1,tag:"ff",type:"mc",q:"„Die Frage hat den Patienten irritiert.“ – Das bedeutet meist:",o:["Sie hat ihn verunsichert.","Sie hat seine Haut gereizt.","Sie hat ihn beruhigt.","Sie hat ihn geheilt."],a:0,why:"irritieren = verwirren, verunsichern. Für Haut und Schleimhaut sagt man reizen."},
{ph:1,tag:"ff",type:"mc",q:"„The ointment irritates the skin.“",o:["Die Salbe reizt die Haut.","Die Salbe irritiert die Haut sehr gern.","Die Salbe verwirrt die Haut."],a:0,why:"Körperlich: reizen. ‚irritieren‘ meint im Deutschen meist: verunsichern."},
{ph:1,tag:"ff",type:"mc",q:"„Der Kollege hat die Fraktur im Röntgenbild übersehen.“ – Das bedeutet:",o:["Er hat sie nicht bemerkt.","Er hat sie überwacht.","Er hat sie sorgfältig geprüft.","Er hat sie überschätzt."],a:0,why:"übersehen = nicht bemerken. ‚oversee‘ heißt beaufsichtigen."},
{ph:1,tag:"ff",type:"mc",q:"„Does the vaccine contain preservatives?“ – Welches Wort ist richtig?",o:["Konservierungsmittel","Präservative","Konserven"],a:0,why:"Das Präservativ ist ein Kondom. preservative = Konservierungsmittel."},
{ph:1,tag:"ff",type:"mc",q:"„Der Patient will nach Hause.“ – Das bedeutet:",o:["Er möchte nach Hause gehen.","Er wird nach Hause gehen.","Er soll nach Hause gehen."],a:0,why:"will kommt von wollen: ein Wunsch. Die Zukunft heißt ‚wird‘."},
{ph:1,tag:"ff",type:"mc",q:"„Der Patient hat also eine Pneumonie.“ – ‚also‘ bedeutet hier:",o:["folglich","auch","außerdem","immer noch"],a:0,why:"also = folglich, demnach. ‚also‘ im Englischen heißt auch."},
{ph:1,tag:"ff",type:"mc",q:"„I spent three hours in the emergency department.“",o:["Ich habe drei Stunden in der Notaufnahme verbracht.","Ich habe drei Stunden in der Notaufnahme gespendet.","Ich habe drei Stunden in der Notaufnahme ausgegeben."],a:0,why:"Zeit verbringen, Geld ausgeben. spenden = to donate."},
{ph:1,tag:"ff",type:"mc",q:"„Wir kontrollieren morgen die Laborwerte.“ – Das bedeutet:",o:["Wir überprüfen sie.","Wir steuern sie.","Wir beherrschen sie.","Wir senken sie."],a:0,why:"kontrollieren = überprüfen. ‚to control‘ heißt steuern, beherrschen."},
{ph:1,tag:"ff",type:"mc",q:"„Die Therapie muss konsequent durchgeführt werden.“ – Das bedeutet:",o:["beständig und ohne Ausnahme","als Folge davon","nacheinander"],a:0,why:"konsequent = folgerichtig, beharrlich. ‚consequently‘ heißt folglich."},
{ph:1,tag:"ff",type:"mc",q:"„He is very sympathetic.“",o:["Er ist sehr mitfühlend.","Er ist sehr sympathisch.","Er ist sehr sympathetisch."],a:0,why:"sympathisch = likeable. sympathetic = mitfühlend, verständnisvoll."},
// ---- phase 2 · Die schiefen Wände: connectors
{ph:2,tag:"konn",type:"mc",q:"Der Befund ist ___ auffällig, ___ nicht bedrohlich.",o:["zwar … aber","sowohl … als auch","weder … noch","je … desto"],a:0,why:"zwar … aber: Einräumung und Einwand."},
{ph:2,tag:"konn",type:"mc",q:"___ länger die Symptome bestehen, ___ schlechter ist die Prognose.",o:["Je … desto","Zwar … aber","Entweder … oder"],a:0,why:"je + Komparativ (Verb am Ende), desto + Komparativ (Verb folgt sofort)."},
{ph:2,tag:"konn",type:"mc",q:"Der Patient hat ___ Fieber ___ Schüttelfrost; er ist nur müde.",o:["weder … noch","sowohl … als auch","nicht nur … sondern auch","entweder … oder"],a:0,why:"weder … noch verneint beides."},
{ph:2,tag:"konn",type:"mc",q:"Wir geben ___ ein Antibiotikum ___ ein Schmerzmittel; beides ist nötig.",o:["sowohl … als auch","entweder … oder","weder … noch"],a:0,why:"sowohl … als auch = das eine und das andere."},
{ph:2,tag:"konn",type:"mc",q:"___ operieren wir heute, ___ wir warten bis morgen.",o:["Entweder … oder","Weder … noch","Sowohl … als auch"],a:0,why:"entweder … oder: eine von zwei Möglichkeiten."},
{ph:2,tag:"konn",type:"order",words:["Trotzdem","möchte","der","Patient","nach","Hause","."],a:"Trotzdem möchte der Patient nach Hause.",why:"trotzdem ist ein Adverb auf Position 1: Das Verb folgt sofort."},
{ph:2,tag:"konn",type:"order",pre:"Der Patient hat starke Schmerzen;",words:["dennoch","lehnt","er","Schmerzmittel","ab","."],a:"dennoch lehnt er Schmerzmittel ab.",why:"dennoch wie trotzdem: Position 1, dann das Verb."},
{ph:2,tag:"konn",type:"order",pre:"Je früher wir behandeln,",words:["desto","besser","ist","die","Prognose","."],a:"desto besser ist die Prognose.",why:"desto + Komparativ zählt als ein Satzteil, dann das Verb."},
{ph:2,tag:"neben",type:"gap",q:"Die Operation verlief gut, ___ der Patient sehr geschwächt war. (although)",a:"obwohl",alt:["obgleich","obschon"],why:"obwohl leitet einen Nebensatz ein (Verb am Ende). trotzdem wäre ein Hauptsatz."},
{ph:2,tag:"neben",type:"gap",q:"Der Blutdruck war sehr niedrig, ___ wir sofort Flüssigkeit gaben. (Folge)",a:"sodass",alt:["so dass","weshalb","weswegen"],why:"sodass nennt die Folge; das Verb steht am Ende."},
{ph:2,tag:"neben",type:"mc",q:"Man senkt das Fieber, ___ man Wadenwickel anlegt.",o:["indem","sodass","obwohl","während"],a:0,why:"indem nennt das Mittel: Wie senkt man das Fieber?"},
{ph:2,tag:"neben",type:"mc",q:"___ der Patient nüchtern ist, können wir heute operieren.",o:["Sofern","Obwohl","Sodass"],a:0,why:"sofern = falls, wenn: eine Bedingung."},
{ph:2,tag:"konn",type:"fix",q:"Er ist nicht nur müde, aber auch verwirrt.",a:"Er ist nicht nur müde, sondern auch verwirrt.",err:"aber",why:"nicht nur … sondern auch. Nach einer Verneinung steht sondern."},
{ph:2,tag:"neben",type:"fix",q:"Obwohl er hat Fieber, arbeitet er.",a:"Obwohl er Fieber hat, arbeitet er.",err:"hat Fieber",why:"obwohl: Verb ans Ende des Nebensatzes."},
{ph:2,tag:"konn",type:"fix",q:"Deshalb wir haben ein CT gemacht.",a:"Deshalb haben wir ein CT gemacht.",err:"wir haben",why:"deshalb steht auf Position 1, also folgt das Verb."},
{ph:2,tag:"konn",type:"mc",q:"„Die Wunde heilt schlecht, weil der Patient raucht.“ – Mit Adverb:",o:["Der Patient raucht; deshalb heilt die Wunde schlecht.","Der Patient raucht; trotzdem heilt die Wunde schlecht.","Der Patient raucht; deshalb die Wunde heilt schlecht."],a:0,why:"Grund → Folge: deshalb + Verb auf Position 2."},
{ph:2,tag:"neben",type:"mc",q:"Wir geben Heparin, ___ eine Thrombose zu verhindern.",o:["um","damit","sodass"],a:0,why:"Gleiches Subjekt (wir): um … zu + Infinitiv."},
{ph:2,tag:"neben",type:"mc",q:"Wir geben Heparin, ___ der Patient keine Thrombose bekommt.",o:["damit","um","indem"],a:0,why:"Neues Subjekt (der Patient): damit + Nebensatz."},
// ---- phase 3 · Die Akten der Anstalt: nominal style and collocations
{ph:3,tag:"nominal",type:"transform",q:"In den Nominalstil: Weil der Blutdruck stark abfiel, wurde der Patient verlegt.",a:"Wegen des starken Blutdruckabfalls wurde der Patient verlegt.",alt:["Aufgrund des starken Blutdruckabfalls wurde der Patient verlegt.","Wegen des starken Abfalls des Blutdrucks wurde der Patient verlegt."],x:["dem","abfiel"],why:"weil + Satz → wegen + Genitiv; das Adverb stark wird Adjektiv: des starken …abfalls."},
{ph:3,tag:"nominal",type:"transform",q:"In den Verbalstil: Nach Eintreffen des Notarztes wurde der Patient intubiert.",a:"Nachdem der Notarzt eingetroffen war, wurde der Patient intubiert.",alt:["Als der Notarzt eingetroffen war, wurde der Patient intubiert."],x:["hatte","nach"],why:"nach + Nomen → nachdem + Plusquamperfekt; eintreffen bildet es mit sein."},
{ph:3,tag:"nominal",type:"transform",q:"In den Nominalstil: bevor der Patient entlassen wird",a:"vor der Entlassung des Patienten",alt:["vor Entlassung des Patienten","vor der Entlassung"],x:["bevor","dem"],why:"bevor → vor + Dativ; der Patient wird Genitivattribut."},
{ph:3,tag:"nominal",type:"transform",q:"In den Verbalstil: bei Verschlechterung des Zustands",a:"wenn sich der Zustand verschlechtert",alt:["falls sich der Zustand verschlechtert","wenn der Zustand sich verschlechtert","falls der Zustand sich verschlechtert","sobald sich der Zustand verschlechtert"],x:["bei","des"],why:"bei + Nomen → wenn / falls; sich verschlechtern ist reflexiv."},
{ph:3,tag:"nominal",type:"transform",q:"In den Nominalstil: obwohl er intensiv behandelt wurde",a:"trotz intensiver Behandlung",alt:["trotz der intensiven Behandlung"],x:["obwohl","intensive"],why:"obwohl → trotz + Genitiv; ohne Artikel trägt das Adjektiv die Endung -er."},
{ph:3,tag:"nominal",type:"transform",q:"In den Verbalstil: zur Vermeidung einer Thrombose",a:"um eine Thrombose zu vermeiden",alt:["damit eine Thrombose vermieden wird"],x:["einer","zur"],why:"zu + Nomen (Zweck) → um … zu; der Genitiv wird Akkusativobjekt."},
{ph:3,tag:"nominal",type:"transform",q:"In den Nominalstil: Der Patient wurde aufgenommen, weil er Atemnot hatte.",a:"Die Aufnahme des Patienten erfolgte wegen Atemnot.",alt:["Die Aufnahme erfolgte wegen Atemnot.","Die Aufnahme des Patienten erfolgte aufgrund von Atemnot.","Der Patient wurde wegen Atemnot aufgenommen."],x:["weil","hatte"],why:"aufnehmen → die Aufnahme + Genitiv; ‚erfolgen‘ ist das blasse Verb des Arztbriefs."},
{ph:3,tag:"nominal",type:"mc",q:"„Es erfolgte die Gabe von 500 ml Infusionslösung.“ – Klar und verbal:",o:["Wir gaben 500 ml Infusionslösung.","Es gab 500 ml Infusionslösung.","500 ml Infusionslösung wurden erfolgt."],a:0,why:"die Gabe → geben. ‚erfolgen‘ hat kein Passiv; ‚es gab‘ heißt there was."},
{ph:3,tag:"nominal",type:"fix",say:"Schlafwandler",q:"Wegen dem Verdacht auf Pneumonie erfolgte eine Röntgenaufnahme.",a:"Wegen des Verdachts auf Pneumonie erfolgte eine Röntgenaufnahme.",err:"dem Verdacht",why:"In der Schriftsprache steht wegen mit dem Genitiv."},
{ph:3,tag:"nominal",type:"fix",say:"Schlafwandler",q:"Unter Berücksichtigung von den Vorerkrankungen wurde die Dosis reduziert.",a:"Unter Berücksichtigung der Vorerkrankungen wurde die Dosis reduziert.",err:"von den",why:"Im Nominalstil steht das Genitivattribut, nicht von + Dativ."},
{ph:3,tag:"nominal",type:"fix",say:"Schlafwandler",q:"Nach erfolgte Aufklärung unterschrieb der Patient.",a:"Nach erfolgter Aufklärung unterschrieb der Patient.",err:"erfolgte",why:"nach + Dativ, feminin, ohne Artikel: Endung -er."},
{ph:3,tag:"nominal",type:"fix",say:"Schlafwandler",q:"Die Verlegung des Patienten hat am Montag stattgenommen.",a:"Die Verlegung des Patienten hat am Montag stattgefunden.",err:"stattgenommen",why:"stattfinden, fand statt, stattgefunden."},
{ph:3,tag:"koll",type:"fix",say:"Schlafwandler",q:"Der Patient wurde über die Risiken informiert und hat seine Einwilligung gemacht.",a:"Der Patient wurde über die Risiken informiert und hat seine Einwilligung gegeben.",alt:["Der Patient wurde über die Risiken informiert und hat seine Einwilligung erteilt."],err:"gemacht",why:"Eine Einwilligung gibt oder erteilt man."},
{ph:3,tag:"koll",type:"mc",q:"Der Oberarzt hat die Verantwortung für die Station ___.",o:["übernommen","genommen","gemacht","geholt"],a:0,why:"Verantwortung übernehmen (oder tragen)."},
{ph:3,tag:"koll",type:"mc",q:"Bitte nehmen Sie Rücksicht ___ die anderen Patienten.",o:["auf","für","an"],a:0,why:"Rücksicht nehmen auf + Akkusativ."},
{ph:3,tag:"koll",type:"mc",q:"Die Patientin hat einen Antrag auf Rehabilitation ___.",o:["gestellt","gemacht","gegeben","gesetzt"],a:0,why:"einen Antrag stellen."},
{ph:3,tag:"koll",type:"mc",q:"Der Patient hat Anspruch ___ eine zweite Meinung.",o:["auf","für","zu"],a:0,why:"Anspruch haben auf + Akkusativ."},
{ph:3,tag:"koll",type:"mc",q:"Das Alter spielt für diese Therapie keine ___.",o:["Rolle","Bedeutung","Funktion"],a:0,why:"eine Rolle spielen. (Bedeutung hat etwas; man spielt sie nicht.)"},
{ph:3,tag:"koll",type:"mc",q:"Wir stehen mit dem Hausarzt in ___.",o:["Kontakt","Beziehung","Berührung"],a:0,why:"mit jemandem in Kontakt stehen."},
{ph:3,tag:"koll",type:"mc",q:"Das neue Medikament kommt erst nächstes Jahr ___ den Markt.",o:["auf","in","an"],a:0,why:"auf den Markt kommen."},
// ---- boss action · Suggestion: agree or contradict (five are true)
{act:"sugg",tag:"ff",type:"mc",q:"Caligari: „‚eventuell‘ bedeutet ‚schließlich, am Ende‘.“",o:["Falsch: ‚eventuell‘ bedeutet ‚vielleicht‘.","Richtig.","Falsch: ‚eventuell‘ bedeutet ‚gleichmäßig‘."],a:0,why:"eventuell = möglicherweise."},
{act:"sugg",tag:"konn",type:"mc",q:"Caligari: „Nach ‚trotzdem‘ steht das Verb am Satzende.“",o:["Falsch: Nach ‚trotzdem‘ folgt sofort das Verb.","Richtig.","Falsch: Nach ‚trotzdem‘ steht zuerst das Subjekt."],a:0,why:"trotzdem ist ein Adverb, keine Subjunktion: Trotzdem arbeitet er."},
{act:"sugg",tag:"neben",type:"mc",q:"Caligari: „‚obwohl‘ leitet einen Nebensatz ein; das Verb steht am Ende.“",o:["Richtig.","Falsch: Das Verb steht auf Position 2.","Falsch: ‚obwohl‘ steht mit dem Genitiv."],a:0,why:"obwohl + Nebensatz. Mit Genitiv steht trotz."},
{act:"sugg",tag:"koll",type:"mc",q:"Caligari: „Man sagt: eine Entscheidung machen.“",o:["Falsch: eine Entscheidung treffen.","Richtig.","Falsch: eine Entscheidung nehmen."],a:0,why:"eine Entscheidung treffen (oder fällen)."},
{act:"sugg",tag:"nominal",type:"mc",q:"Caligari: „In der Schriftsprache steht ‚wegen‘ mit dem Genitiv.“",o:["Richtig.","Falsch: immer mit dem Dativ.","Falsch: mit dem Akkusativ."],a:0,why:"wegen des Befundes. Der Dativ ist Umgangssprache."},
{act:"sugg",tag:"ff",type:"mc",q:"Caligari: „‚Der Arzt kontrolliert den Blutdruck‘ heißt: Er überprüft ihn.“",o:["Richtig.","Falsch: Er senkt ihn.","Falsch: Er steuert ihn."],a:0,why:"kontrollieren = überprüfen."},
{act:"sugg",tag:"koll",type:"mc",q:"Caligari: „Korrekt ist: Ich bin interessiert für Kardiologie.“",o:["Falsch: Ich interessiere mich für Kardiologie.","Richtig.","Falsch: Ich bin interessiert auf Kardiologie."],a:0,why:"sich interessieren für + Akk. — oder: interessiert sein an + Dat."},
{act:"sugg",tag:"konn",type:"mc",q:"Caligari: „Nach ‚desto‘ und dem Komparativ kommt sofort das Verb.“",o:["Richtig.","Falsch: Das Verb steht am Ende.","Falsch: Zuerst kommt das Subjekt."],a:0,why:"…, desto besser ist die Prognose."},
{act:"sugg",tag:"passiv",type:"mc",q:"Caligari: „‚Der Patient wurde operiert‘ und ‚Der Patient ist operiert‘ bedeuten dasselbe.“",o:["Falsch: ‚wurde‘ ist der Vorgang, ‚ist‘ der Zustand danach.","Richtig.","Falsch: ‚ist operiert‘ ist kein Deutsch."],a:0,why:"Vorgangspassiv (werden) und Zustandspassiv (sein)."},
{act:"sugg",tag:"ff",type:"mc",q:"Caligari: „‚sensibel‘ heißt ‚vernünftig‘.“",o:["Falsch: ‚sensibel‘ heißt ‚empfindlich‘.","Richtig.","Falsch: ‚sensibel‘ heißt ‚spürbar‘."],a:0,why:"vernünftig ist ‚sensible‘."},
{act:"sugg",tag:"nominal",type:"mc",q:"Caligari: „Im Nominalstil wird aus ‚weil er stürzte‘: ‚wegen seines Sturzes‘.“",o:["Richtig.","Falsch: ‚wegen sein Sturz‘.","Falsch: ‚trotz seines Sturzes‘."],a:0,why:"weil → wegen + Genitiv; stürzen → der Sturz."},
{act:"sugg",tag:"koll",type:"mc",q:"Caligari: „Rücksicht nimmt man ‚für‘ jemanden.“",o:["Falsch: Rücksicht nehmen auf jemanden.","Richtig.","Falsch: Rücksicht nehmen an jemandem."],a:0,why:"Rücksicht nehmen auf + Akkusativ."}];
// ---------------------------------------------------------------- Die Kommission (C1, chapter 40) — rewritten by i7 on Frau Brandt (PLAN-I R1): Simulationspatientin, 71, Luftnot.
// Case (from I10 BV_CAST.brandt; the dog is never named): Luftnot seit drei Tagen zunehmend, nachts erwacht, drei Kissen, Knöchel dick, 3 kg in einer Woche,
// Nykturie; bekannt: Herzschwäche nach Infarkt 2021, Vorhofflimmern, COPD, Nieren; Wassertablette an Ausgehtagen weggelassen; Penicillin-Ausschlag;
// Ex-Raucherin (30 Packungsjahre, bis 2019); abends ein Glas Rotwein; Vater † mit 58 (Herzinfarkt); allein, 2. Stock ohne Aufzug.
// Room 1: three options each — one correct in form AND lay register; one with a grammar error; one in the wrong register (technical term, du, suggestive).
// ans = what she answers after a correct question (kept on the notepad: room 2 documents these sentences).
BOSS2.kommission.items=[
// ---- room 1 · Anamnese
{ph:1,head:"Begrüßung",tag:"register",type:"mc",q:"Sie betreten das Zimmer. Ihr erster Satz:",o:["Guten Tag, Frau Brandt. Mein Name ist Dr. {LAST}, ich bin der diensthabende Arzt. Was führt Sie zu uns?","Hallo, ich bin der Doktor. Was hast du denn?","Guten Tag. Welche Symptomatik liegt bei Ihnen vor?"],a:0,ans:"Guten Tag, Herr Doktor. Ich kriege seit drei Tagen immer schlechter Luft.",why:"Name, Funktion, offene Frage. Kein du, keine Fachsprache."},
{ph:1,head:"Aktuelle Beschwerden",tag:"register",type:"mc",q:"Sie fragen, wann die Luftnot auftritt.",o:["Wann ist die Luftnot schlimmer – wenn Sie sich bewegen, oder auch in Ruhe?","Besteht eine Belastungs- oder eine Ruhedyspnoe?","Wann ist die Luftnot schlimmer – wenn Sie bewegen, oder auch in Ruhe?"],a:0,ans:"Schon beim Anziehen. Die Treppe schaffe ich nur noch mit zwei Pausen.",why:"Laiensprache; sich bewegen ist reflexiv."},
{ph:1,head:"Aktuelle Beschwerden",tag:"satzbau",type:"mc",q:"Sie fragen nach der Luftnot im Liegen.",o:["Wie viele Kissen brauchen Sie nachts, um gut Luft zu bekommen?","Wie viel Kissen brauchen Sie nachts, um gut Luft bekommen?","Haben Sie eine Orthopnoe?"],a:0,ans:"Drei. Und letzte Nacht habe ich im Sessel geschlafen.",why:"wie viele + Plural; um … zu + Infinitiv. ‚Orthopnoe‘ versteht sie nicht."},
{ph:1,head:"Aktuelle Beschwerden",tag:"satzbau",type:"mc",q:"Sie fragen, ob sie nachts aufwacht.",o:["Sind Sie nachts schon einmal aufgewacht, weil Sie keine Luft bekommen haben?","Haben Sie nachts schon einmal aufgewacht, weil Sie keine Luft bekommen haben?","Leiden Sie unter paroxysmaler nächtlicher Dyspnoe?"],a:0,ans:"Ja, heute Nacht. Es hat mich aus dem Schlaf gerissen.",why:"aufwachen bildet das Perfekt mit sein: Sind Sie aufgewacht?"},
{ph:1,head:"Aktuelle Beschwerden",tag:"kasus",type:"mc",q:"Sie fragen nach Husten.",o:["Haben Sie Husten? Und wenn ja: Husten Sie dabei etwas ab?","Haben Sie Husten? Und wenn ja: mit einen Auswurf?","Besteht ein produktiver Husten mit Expektoration?"],a:0,ans:"Nachts, ja. Weißen Schaum, ein bisschen.",why:"mit + Dativ (mit einem Auswurf). Einfacher noch: Husten Sie etwas ab?"},
{ph:1,head:"Aktuelle Beschwerden",tag:"kasus",type:"mc",q:"Sie fragen nach geschwollenen Beinen.",o:["Sind Ihre Beine in letzter Zeit dicker geworden, zum Beispiel an den Knöcheln?","Sind Ihre Beine in letzter Zeit dicker geworden, zum Beispiel an die Knöchel?","Haben Sie periphere Ödeme bemerkt?"],a:0,ans:"Die Knöchel, ja. Die Schuhe gehen abends kaum noch zu.",why:"wo? → an + Dativ: an den Knöcheln."},
{ph:1,head:"Aktuelle Beschwerden",tag:"satzbau",type:"mc",q:"Sie fragen nach dem Gewicht.",o:["Haben Sie in den letzten Tagen zugenommen? Wiegen Sie sich regelmäßig?","Haben Sie in den letzten Tagen zugenommen? Wiegen Sie regelmäßig sich?","Liegt eine Gewichtszunahme vor?"],a:0,ans:"Drei Kilo in einer Woche, sagt meine Tochter. Ich selbst wiege mich nie.",why:"Das Reflexivpronomen steht direkt nach dem Subjekt: Wiegen Sie sich …"},
{ph:1,head:"Aktuelle Beschwerden",tag:"kasus",type:"mc",q:"Sie fragen nach Schmerzen in der Brust.",o:["Haben Sie dabei Schmerzen oder ein Engegefühl in der Brust?","Haben Sie dabei Schmerzen oder ein Engegefühl in die Brust?","Bestehen pektanginöse Beschwerden?"],a:0,ans:"Schmerzen nicht. Nur eng, wenn ich keine Luft kriege.",why:"wo? → in + Dativ: in der Brust."},
{ph:1,head:"Aktuelle Beschwerden",tag:"register",type:"mc",q:"Sie fragen nach Herzstolpern.",o:["Spüren Sie manchmal, dass Ihr Herz rast oder stolpert?","Haben Sie Palpitationen?","Spüren Sie manchmal, dass Ihr Herz rast oder stolpert sich?"],a:0,ans:"Das Herz stolpert schon lange. Das kenne ich.",why:"Herzrasen, Herzstolpern: Alltagswörter. stolpern ist nicht reflexiv."},
{ph:1,head:"Vorerkrankungen",tag:"kasus",type:"mc",q:"Sie fragen nach Vorerkrankungen.",o:["Welche Erkrankungen sind bei Ihnen bekannt – zum Beispiel am Herzen oder an der Lunge?","Welche Erkrankungen sind bei Ihnen bekannt – zum Beispiel am Herzen oder an die Lunge?","Welche kardiopulmonalen Vorerkrankungen bestehen?"],a:0,ans:"Das Herz ist schwach, seit dem Infarkt vor fünf Jahren. Es stolpert. Und die Lunge, vom Rauchen.",why:"wo? → an + Dativ: an der Lunge."},
{ph:1,head:"Medikamente",tag:"koll",type:"mc",q:"Sie fragen nach Medikamenten.",o:["Welche Medikamente nehmen Sie ein, und wie oft?","Welche Medikamente nehmen Sie an, und wie oft?","Wie sieht Ihre Dauermedikation aus?"],a:0,ans:"Die Wassertablette, den Blutverdünner, zwei fürs Herz, eine fürs Cholesterin und das Spray für die Lunge.",why:"Medikamente nimmt man ein. ‚Dauermedikation‘ ist Fachsprache."},
{ph:1,head:"Medikamente",tag:"satzbau",type:"mc",q:"Sie fragen, ob sie die Tabletten regelmäßig nimmt.",o:["Kommt es vor, dass Sie eine Tablette weglassen – zum Beispiel, wenn Sie unterwegs sind?","Kommt es vor, dass Sie lassen eine Tablette weg – zum Beispiel, wenn Sie unterwegs sind?","Sind Sie adhärent?"],a:0,ans:"Die Wassertablette lasse ich weg, wenn ich aus dem Haus muss. Wegen der Toilette.",why:"dass-Satz: Das Verb steht am Ende, und weglassen bleibt zusammen."},
{ph:1,head:"Allergien",tag:"kasus",type:"mc",q:"Sie fragen nach Allergien.",o:["Haben Sie Allergien, zum Beispiel gegen Medikamente?","Haben Sie Allergien, zum Beispiel an Medikamente?","Sind Arzneimittelunverträglichkeiten anamnestisch bekannt?"],a:0,ans:"Gegen Penicillin. Da kriege ich Ausschlag.",why:"eine Allergie gegen + Akkusativ."},
{ph:1,head:"Noxen",tag:"satzbau",type:"mc",q:"Sie fragen nach dem Rauchen.",o:["Rauchen Sie, oder haben Sie früher geraucht?","Rauchen Sie, oder haben Sie früher gerauchen?","Besteht ein Nikotinabusus?"],a:0,ans:"Dreißig Jahre lang eine Schachtel am Tag. Aufgehört habe ich 2019.",why:"rauchen ist schwach: geraucht."},
{ph:1,head:"Noxen",tag:"register",type:"mc",q:"Sie fragen nach Alkohol.",o:["Trinken Sie Alkohol? Wie viel ungefähr?","Sie trinken aber nicht zu viel, oder?","Besteht ein Alkoholabusus?"],a:0,ans:"Abends ein Glas Rotwein. Eins.",why:"Offen, wertfrei, mit Mengenfrage. Keine Suggestivfrage."},
{ph:1,head:"Familienanamnese",tag:"kasus",type:"mc",q:"Sie fragen nach der Familie.",o:["Gibt es in Ihrer Familie Herzerkrankungen?","Gibt es in Ihre Familie Herzerkrankungen?","Ist die Familienanamnese kardiovaskulär positiv?"],a:0,ans:"Mein Vater ist mit achtundfünfzig am Herzinfarkt gestorben.",why:"wo? → in + Dativ: in Ihrer Familie."},
{ph:1,head:"Sozialanamnese",tag:"register",type:"mc",q:"Sie fragen, wie sie wohnt.",o:["Wie wohnen Sie – leben Sie allein, und gibt es bei Ihnen Treppen?","Wie wohnst du denn so?","Wie stellt sich Ihre häusliche Versorgungssituation dar?"],a:0,ans:"Allein, im zweiten Stock, ohne Aufzug. Einunddreißig Stufen. Ich habe sie gezählt.",why:"Alltagssprache, Sie-Form, konkrete Frage."},
{ph:1,head:"Vegetative Anamnese",tag:"satzbau",type:"mc",q:"Sie fragen nach Appetit, Schlaf, Stuhlgang und Wasserlassen.",o:["Hat sich in letzter Zeit etwas an Appetit, Schlaf, Stuhlgang oder Wasserlassen verändert?","Hat in letzter Zeit etwas an Appetit, Schlaf, Stuhlgang oder Wasserlassen verändert?","Gibt es Auffälligkeiten in der vegetativen Anamnese?"],a:0,ans:"Ich muss nachts dreimal raus. Appetit habe ich kaum.",why:"sich verändern ist reflexiv: Hat sich … verändert?"},
{ph:1,head:"Verdacht erklären",tag:"register",type:"mc",q:"Sie erklären der Patientin Ihren Verdacht.",o:["Ich vermute, dass Ihr Herz im Moment zu schwach pumpt und sich deshalb Wasser in der Lunge und in den Beinen sammelt.","Ich vermute, dass Ihr Herz im Moment pumpt zu schwach.","Ich vermute eine akute kardiale Dekompensation."],a:0,ans:"Das Herz. Schon wieder. Und das Wasser kommt davon?",why:"Verdacht in Laiensprache; im dass-Satz steht das Verb am Ende."},
{ph:1,head:"Nächste Schritte",tag:"register",type:"mc",q:"Sie erklären, was jetzt geschieht.",o:["Wir möchten Sie heute hierbehalten. Wir schreiben ein EKG, röntgen die Lunge und machen einen Ultraschall vom Herzen.","Wir veranlassen ein Röntgen-Thorax, eine TTE und ein NT-proBNP.","Wir möchten, dass Sie bleiben heute hier."],a:0,ans:"Hierbleiben. Dann muss jemand meine Nachbarin anrufen, wegen des Hundes.",why:"Laiensprache; im dass-Satz stünde das Verb am Ende: dass Sie heute hierbleiben."},
{ph:1,head:"Abschluss",tag:"satzbau",type:"mc",q:"Sie schließen das Gespräch ab.",o:["Habe ich etwas vergessen, oder möchten Sie noch etwas ergänzen?","Habe ich etwas vergessen, oder Sie möchten noch etwas ergänzen?","Damit ist die Anamnese komplett."],a:0,ans:"Nein. Sie haben sogar nach dem Wein gefragt. Das tun die wenigsten.",why:"Nach oder beginnt ein neuer Fragesatz: Verb zuerst, möchten Sie."},
// interruptions (boss action in room 1)
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Darf ich mich aufsetzen? Im Liegen kriege ich keine Luft.“",o:["Natürlich. Ich stelle das Kopfteil hoch – sagen Sie mir, wenn es so besser ist.","Bitte bleiben Sie liegen, sonst kann ich Sie nicht untersuchen.","Ja, setzen Sie sich auf, dann Sie bekommen besser Luft."],a:0,why:"Sofort helfen und es sagen. (Nach dann folgt das Verb: dann bekommen Sie …)"},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Was heißt denn ‚Ödeme‘? Das Wort kenne ich nicht.“",o:["Entschuldigung – ich meine Wasser in den Beinen, also geschwollene Beine.","Ödeme sind Flüssigkeitsansammlungen im Gewebe.","Das ist nicht so wichtig."],a:0,why:"Das Fachwort zurücknehmen und in Alltagssprache sagen."},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Sie reden so schnell. Ich war Souffleuse, ich höre jedes Wort – aber nicht so schnell.“",o:["Entschuldigen Sie bitte. Ich wiederhole die Frage langsamer.","Das tut mir leid, aber wir haben wenig Zeit.","Dann hören Sie bitte genauer zu."],a:0,why:"Sich entschuldigen und das Verhalten ändern."},
{ph:1,intr:true,say:"Prüferin",tag:"reaktion",type:"mc",q:"„Etwas zügiger, bitte. Sie haben noch fünf Minuten.“",o:["Selbstverständlich. Frau Brandt, ich habe noch einige kurze Fragen an Sie.","Entschuldigung, ich bin fast fertig, glaube ich, vielleicht.","Ja, ja. Gleich."],a:0,why:"Kurz bestätigen und sofort zur Patientin zurück. eine Frage an jemanden haben."},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Muss ich hierbleiben? Mein Hund ist bei der Nachbarin, aber nur bis heute Abend.“",o:["Ich glaube, ja – für ein paar Tage. Wir rufen Ihre Nachbarin gern an, damit Ihr Hund versorgt ist.","Das klären wir später. Jetzt geht es um Ihre Gesundheit.","Ja. Um den Hund kann ich mich nicht kümmern."],a:0,why:"Ehrlich antworten und die Sorge ernst nehmen: damit + Nebensatz."},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Mir ist ganz blümerant.“",o:["Entschuldigung, dieses Wort kenne ich nicht. Können Sie mir beschreiben, wie es sich anfühlt?","Ja, ich verstehe.","Wie bitte? Sprechen Sie bitte Hochdeutsch!"],a:0,why:"Nachfragen ist besser als raten. (blümerant = flau, schwindlig.)"},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Ist das wieder das Herz? Meine Hausärztin sagt, es ist die Lunge.“",o:["Das kann ich noch nicht sicher sagen. Deshalb untersuchen wir heute beides – das Herz und die Lunge.","Ihre Hausärztin hat sich geirrt.","Ja, wahrscheinlich ist es nur die Lunge."],a:0,why:"Weder die Kollegin abwerten noch ohne Befund beruhigen. deshalb + Verb."},
{ph:1,intr:true,say:"Frau Brandt",tag:"reaktion",type:"mc",q:"„Meine Tochter weiß noch gar nicht, dass ich hier bin.“",o:["Möchten Sie, dass wir Ihre Tochter anrufen? Oder möchten Sie es ihr lieber selbst sagen?","Das ist jetzt nicht das Thema.","Ihre Tochter muss sofort kommen."],a:0,why:"Das Anliegen aufnehmen und ein Angebot machen – die Entscheidung bleibt bei ihr."},
// resume items (the turn after an interruption)
{ph:1,resume:true,tag:"koll",type:"mc",q:"Sie nehmen den Faden wieder auf.",o:["Ich würde gern noch einmal auf Ihre Luftnot zurückkommen.","Ich würde gern noch einmal an Ihre Luftnot zurückkommen.","Also, wo war ich. Egal."],a:0,why:"auf etwas zurückkommen."},
{ph:1,resume:true,tag:"satzbau",type:"mc",q:"Sie nehmen den Faden bei den Tabletten wieder auf.",o:["Sie hatten vorhin erwähnt, dass Sie eine Wassertablette nehmen. Wie heißt sie genau?","Sie hatten vorhin erwähnt, dass Sie nehmen eine Wassertablette. Wie heißt sie?","Vorhin: Tabletten. Welche?"],a:0,why:"dass-Satz: Verb am Ende. Ganze Sätze, auch unter Zeitdruck."},
{ph:1,resume:true,tag:"satzbau",type:"mc",q:"Frau Brandt erzählt lange vom Theater. Sie müssen unterbrechen.",o:["Darf ich Sie kurz unterbrechen? Ich möchte sicher sein, dass ich Sie richtig verstanden habe.","Stopp. Das gehört nicht hierher.","Darf ich Sie kurz unterbrechen? Ich möchte sicher sein, dass ich habe Sie richtig verstanden."],a:0,why:"Höflich unterbrechen; im dass-Satz steht habe am Ende."},
{ph:1,resume:true,tag:"satzbau",type:"mc",q:"Sie fassen zusammen, um weiterzumachen.",o:["Wenn ich Sie richtig verstehe, bekommen Sie seit drei Tagen immer schlechter Luft, vor allem im Liegen. Stimmt das?","Wenn ich verstehe Sie richtig, Sie bekommen seit drei Tagen schlechter Luft. Stimmt?","Dyspnoe seit drei Tagen, Orthopnoe. Korrekt?"],a:0,why:"wenn-Satz mit dem Verb am Ende, danach sofort das Verb des Hauptsatzes: bekommen Sie."},
// ---- room 2 · Dokumentation (the transform prompts quote her answers from the notepad)
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Ich kriege seit drei Tagen immer schlechter Luft.“",a:"Seit drei Tagen zunehmende Dyspnoe.",alt:["Zunehmende Dyspnoe seit drei Tagen.","Seit 3 Tagen zunehmende Dyspnoe.","Seit drei Tagen progrediente Dyspnoe.","Progrediente Dyspnoe seit drei Tagen."],x:["Luft","schlechter"],why:"Luftnot = Dyspnoe; ‚immer schlechter‘ = zunehmend; der Befund steht als Nominalgruppe ohne Verb."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Drei. Und letzte Nacht habe ich im Sessel geschlafen.“ (Kissen)",a:"Orthopnoe (drei Kissen).",alt:["Orthopnoe mit drei Kissen.","Orthopnoe, schläft mit drei Kissen.","Orthopnoe (3 Kissen)."],x:["Sessel","geschlafen"],why:"Atemnot im Liegen = Orthopnoe; die Zahl der Kissen zeigt, wie stark."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Es hat mich aus dem Schlaf gerissen.“",a:"Paroxysmale nächtliche Dyspnoe.",alt:["Nächtliche Atemnotattacke.","Paroxysmale nächtliche Atemnot."],x:["Schlaf","gerissen"],why:"plötzliche Atemnot, die aus dem Schlaf weckt = paroxysmale nächtliche Dyspnoe."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Die Knöchel, ja. Die Schuhe gehen abends kaum noch zu.“",a:"Beidseitige Knöchelödeme.",alt:["Knöchelödeme beidseits.","Beinödeme beidseits.","Beidseitige Beinödeme.","Periphere Ödeme beidseits."],x:["Schuhe","dicke"],why:"geschwollene Knöchel = Knöchelödeme; ‚beidseits‘ gehört dazu."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Drei Kilo in einer Woche, sagt meine Tochter.“",a:"Gewichtszunahme von drei Kilogramm in einer Woche.",alt:["Gewichtszunahme um drei Kilogramm in einer Woche.","Gewichtszunahme von 3 kg in einer Woche.","Gewichtszunahme um 3 kg in einer Woche."],x:["Kilo","zugenommen"],why:"zunehmen → die Gewichtszunahme; im Brief Kilogramm oder kg."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Ich muss nachts dreimal raus.“",a:"Nykturie (dreimal pro Nacht).",alt:["Nykturie, dreimal pro Nacht.","Nykturie (3× pro Nacht).","Nykturie."],x:["raus","muss"],why:"nächtliches Wasserlassen = Nykturie."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Gegen Penicillin. Da kriege ich Ausschlag.“",a:"Penicillinallergie (Exanthem).",alt:["Allergie gegen Penicillin (Exanthem).","Penicillinallergie mit Exanthem.","Allergie gegen Penicillin mit Exanthem."],x:["Ausschlag","kriege"],why:"Ausschlag = Exanthem; die Reaktion steht in Klammern."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Dreißig Jahre lang eine Schachtel am Tag. Aufgehört habe ich 2019.“",a:"Ex-Raucherin, 30 Packungsjahre.",alt:["Ex-Raucherin (30 Packungsjahre).","Ehemaliger Nikotinkonsum von 30 Packungsjahren.","Ex-Raucherin, 30 Packungsjahre, bis 2019."],x:["Schachtel","raucht"],why:"1 Schachtel × 30 Jahre = 30 Packungsjahre; ‚Ex-‘, weil sie aufgehört hat."},
{ph:2,tag:"fach",type:"transform",q:"Dokumentieren Sie: „Mein Vater ist mit achtundfünfzig am Herzinfarkt gestorben.“",a:"Vater mit 58 Jahren an einem Myokardinfarkt verstorben.",alt:["Vater mit 58 Jahren an Myokardinfarkt verstorben.","Der Vater verstarb mit 58 Jahren an einem Myokardinfarkt.","Vater mit 58 an einem Myokardinfarkt verstorben."],x:["gestorben","Herzinfarkt"],why:"Herzinfarkt = Myokardinfarkt; im Brief: verstorben; versterben an + Dativ."},
{ph:2,tag:"brief",type:"order",words:["Die","Patientin","stellte","sich","mit","zunehmender","Dyspnoe","vor","."],a:"Die Patientin stellte sich mit zunehmender Dyspnoe vor.",why:"sich vorstellen mit + Dativ; Präteritum; das Präfix schließt den Satz."},
{ph:2,tag:"brief",type:"order",pre:"Die Patientin gab an,",words:["seit","drei","Tagen","unter","Luftnot","zu","leiden","."],a:"seit drei Tagen unter Luftnot zu leiden.",why:"angeben + Infinitiv mit zu; leiden unter + Dativ."},
{ph:2,tag:"konj1",type:"order",pre:"Sie berichtete,",words:["sie","sei","nachts","mit","Atemnot","erwacht","."],a:"sie sei nachts mit Atemnot erwacht.",why:"Indirekte Rede ohne dass: Konjunktiv I auf Position 2; erwachen bildet das Perfekt mit sein."},
{ph:2,tag:"brief",type:"order",words:["Fieber","und","Brustschmerzen","wurden","verneint","."],a:"Fieber und Brustschmerzen wurden verneint.",alt:["Brustschmerzen und Fieber wurden verneint."],why:"Was die Patientin nicht hat, wird im Passiv ‚verneint‘."},
{ph:2,tag:"brief",type:"order",pre:"Bei Verdacht auf eine kardiale Dekompensation",words:["erfolgte","die","stationäre","Aufnahme","."],a:"erfolgte die stationäre Aufnahme.",why:"Die Präpositionalgruppe steht auf Position 1, also folgt das Verb: erfolgte."},
{ph:2,tag:"konj1",type:"gap",q:"Die Patientin gibt an, sie ___ das Diuretikum an einzelnen Tagen weg. (lassen, Konjunktiv I)",a:"lasse",alt:[],why:"sie lasse … weg: Stamm + -e. Der Indikativ hieße lässt."},
{ph:2,tag:"konj1",type:"gap",q:"Die Beschwerden ___ laut Patientin im Liegen stärker. (sein, Konjunktiv I)",a:"seien",alt:[],why:"sie seien: Der Plural von sein hat eine eigene Konjunktiv-I-Form."},
{ph:2,tag:"praep",type:"mc",q:"___ der bekannten Herzinsuffizienz ist eine Dekompensation wahrscheinlich.",o:["Aufgrund","Mittels","Anlässlich"],a:0,why:"aufgrund + Genitiv nennt den Grund."},
{ph:2,tag:"kasus",type:"fix",say:"Prüfer",q:"Die Patientin klagt über zunehmenden Luftnot.",a:"Die Patientin klagt über zunehmende Luftnot.",err:"zunehmenden",why:"klagen über + Akkusativ; die Luftnot ist feminin: zunehmende Luftnot."},
{ph:2,tag:"praep",type:"fix",say:"Prüfer",q:"Die Medikation besteht unter anderem von Torasemid und Apixaban.",a:"Die Medikation besteht unter anderem aus Torasemid und Apixaban.",err:"von",why:"bestehen aus + Dativ."},
{ph:2,tag:"brief",type:"mc",q:"In welcher Form steht die Anamnese im Arztbrief meist?",o:["im Präteritum, die Angaben der Patientin im Konjunktiv I","im Perfekt und in der Ich-Form","im Futur"],a:0,why:"Der Brief berichtet (Präteritum) und gibt wieder (Konjunktiv I)."},
// ---- room 3 · Fallvorstellung und Prüferfragen
{ph:3,tag:"brief",type:"order",words:["Ich","möchte","Ihnen","Frau","Brandt","vorstellen","."],a:"Ich möchte Ihnen Frau Brandt vorstellen.",why:"Dativ (Ihnen) vor Akkusativ (Frau Brandt); vorstellen steht am Ende."},
{ph:3,tag:"endung",type:"gap",q:"Frau Brandt ist eine 71-___ Patientin. (jährig)",a:"jährige",alt:["jährige Patientin"],why:"Nach eine, feminin, Nominativ: -e."},
{ph:3,tag:"praep",type:"order",pre:"Sie stellte sich",words:["wegen","seit","drei","Tagen","zunehmender","Luftnot","vor","."],a:"wegen seit drei Tagen zunehmender Luftnot vor.",why:"wegen + Genitiv ohne Artikel: zunehmender Luftnot; die Zeitangabe steht vor dem Partizip."},
{ph:3,tag:"satzbau",type:"gap",q:"An Vorerkrankungen ___ eine Herzinsuffizienz, ein Vorhofflimmern und eine COPD bekannt. (sein)",a:"sind",alt:[],why:"Drei Subjekte: Plural. Das Verb steht nach der ersten Satzgruppe."},
{ph:3,tag:"koll",type:"order",words:["Die","Anamnese","deutet","auf","eine","kardiale","Dekompensation","hin","."],a:"Die Anamnese deutet auf eine kardiale Dekompensation hin.",why:"hindeuten auf + Akkusativ; hin am Satzende."},
{ph:3,tag:"koll",say:"Vorsitzende",type:"mc",q:"„Welche Differenzialdiagnosen ziehen Sie in Betracht?“",o:["Differenzialdiagnostisch kommen eine exazerbierte COPD, eine Pneumonie und eine Lungenembolie in Betracht.","Ich denke vielleicht an die Lunge oder so, oder an ein Gerinnsel.","Differenzialdiagnostisch kommt eine exazerbierte COPD, eine Pneumonie und eine Lungenembolie in Betracht gezogen."],a:0,why:"in Betracht kommen (Plural: kommen) – oder: in Betracht ziehen. Nicht beides."},
{ph:3,tag:"satzbau",say:"Prüfer",type:"mc",q:"„Welche Untersuchungen ordnen Sie zuerst an?“",o:["Zunächst würde ich ein EKG schreiben, den Thorax röntgen und das NT-proBNP bestimmen lassen.","Zunächst ich würde ein EKG machen und das BNP.","Ich mache ein EKG schreiben und nehme BNP."],a:0,why:"zunächst + Verb; ein EKG schreiben; etwas bestimmen lassen."},
{ph:3,tag:"register",say:"Prüferin",type:"mc",q:"„Wie erklären Sie der Patientin den Herzultraschall?“",o:["Wir schauen uns Ihr Herz mit Ultraschall von außen an. Dafür kommt etwas Gel auf die Brust; das tut nicht weh.","Wir führen eine transthorakale Echokardiographie durch.","Wir machen ein Ultraschall in das Herz und gucken."],a:0,why:"Für die Patientin: von außen, Gel, tut nicht weh. Ganze, korrekte Sätze."},
{ph:3,intr:true,tag:"fach",say:"Prüfer",type:"mc",q:"„Einen Moment. Was meinen Sie mit ‚Orthopnoe‘?“",o:["Damit meine ich Atemnot im Liegen, die sich im Sitzen bessert.","Orthopnoe ist Orthopnoe, also die Luftnot.","Das bedeutet Atemnot beim Treppensteigen."],a:0,why:"Damit meine ich …: einen Begriff definieren."},
{ph:3,intr:true,tag:"koll",say:"Vorsitzende",type:"mc",q:"„Und wenn die Patientin die stationäre Aufnahme ablehnt?“",o:["Dann kläre ich sie erneut über die Risiken auf, dokumentiere die Ablehnung und lasse sie mir unterschreiben.","Dann überrede ich sie, bis sie zustimmt.","Dann wird sie eben gegen ihren Willen aufgenommen."],a:0,why:"jemanden über etwas aufklären; etwas dokumentieren; sich etwas unterschreiben lassen."},
{ph:3,resume:true,tag:"koll",type:"mc",q:"Sie kehren zu Ihrer Fallvorstellung zurück.",o:["Ich komme nun auf die weiteren Untersuchungen zurück.","Ich komme nun auf den weiteren Untersuchungen zurück.","Egal. Weiter."],a:0,why:"zurückkommen auf + Akkusativ: auf die weiteren Untersuchungen."},
{ph:3,resume:true,tag:"satzbau",type:"mc",q:"Sie greifen die Frage auf und machen weiter.",o:["Um auf Ihre Frage zurückzukommen: Das NT-proBNP würde ich sofort bestimmen lassen.","Um auf Ihre Frage zurückzukommen: Das NT-proBNP ich würde sofort bestimmen lassen.","Wie gesagt, BNP."],a:0,why:"Nach dem Doppelpunkt ein ganzer Hauptsatz: Verb auf Position 2."},
{ph:3,tag:"term",type:"mc",q:"Dyspnoe — so sagen Sie es der Patientin:",o:["Atemnot","Schluckbeschwerden","Herzrasen","Brustenge"],a:0,why:"Dyspnoe = Atemnot. (Dysphagie = Schluckbeschwerden, Tachykardie = Herzrasen.)"},
{ph:3,tag:"term",type:"mc",q:"Orthopnoe — so sagen Sie es der Patientin:",o:["Atemnot im Liegen","Atemnot beim Gehen","Husten in der Nacht","Schnarchen"],a:0,why:"Orthopnoe = Atemnot im Liegen, besser im Sitzen."},
{ph:3,tag:"term",type:"mc",q:"Ödeme — so sagen Sie es der Patientin:",o:["Wassereinlagerungen","Blutergüsse","Krampfadern","Hautausschlag"],a:0,why:"Ödem = Wassereinlagerung, geschwollene Beine. (Hämatom = Bluterguss, Varizen = Krampfadern.)"},
{ph:3,tag:"term",type:"mc",q:"Diuretikum — so sagen Sie es der Patientin:",o:["Wassertablette","Blutverdünner","Schmerzmittel","Beruhigungsmittel"],a:0,why:"Diuretikum = harntreibendes Mittel; Patienten sagen ‚Wassertablette‘."},
{ph:3,tag:"term",type:"mc",q:"Antikoagulans — so sagen Sie es der Patientin:",o:["Blutverdünner","Wassertablette","Blutdrucksenker","Schlafmittel"],a:0,why:"Antikoagulans = gerinnungshemmendes Mittel; Patienten sagen meist ‚Blutverdünner‘."},
{ph:3,tag:"term",type:"gap",q:"„Herzschwäche“ – der Fachbegriff:",a:"Herzinsuffizienz",alt:["die Herzinsuffizienz"],why:"Insuffizienz = ungenügende Leistung; hier des Herzens."},
{ph:3,tag:"term",type:"gap",q:"„Wasser in der Lunge“ – der Fachbegriff:",a:"Lungenödem",alt:["das Lungenödem","Lungenstauung","pulmonale Stauung","die pulmonale Stauung"],why:"Flüssigkeit im Lungengewebe = Lungenödem; geringer: pulmonale Stauung."},
{ph:3,tag:"endung",type:"fix",say:"Prüfer",q:"Ich würde den Befund mit dem Oberarzt und dem Kollege der Kardiologie besprechen.",a:"Ich würde den Befund mit dem Oberarzt und dem Kollegen der Kardiologie besprechen.",err:"Kollege",why:"n-Deklination: dem Kollegen."},
{ph:3,tag:"koll",type:"mc",q:"Das erhöhte NT-proBNP ___ für eine kardiale Ursache.",o:["spricht","sagt","redet"],a:0,why:"für etwas sprechen = auf etwas hinweisen."},
{ph:3,tag:"satzbau",type:"gap",q:"Therapeutisch ___ ich zunächst ein intravenöses Diuretikum empfehlen. (werden, Konjunktiv II)",a:"würde",alt:[],why:"Vorschlag im Kollegengespräch: würde + Infinitiv."},
{ph:3,tag:"kasus",type:"fix",say:"Prüferin",q:"Auskultatorisch hörte man feuchte Rasselgeräusche über die basalen Lungenabschnitte.",a:"Auskultatorisch hörte man feuchte Rasselgeräusche über den basalen Lungenabschnitten.",err:"die basalen Lungenabschnitte",why:"wo? → über + Dativ: über den basalen Lungenabschnitten."}];
// hard mode "Dialekt": notepad variants of six of her answers (display only). Kurpfälzisch approximation by i7 — NOT checked by a native speaker (MANIFEST: facts to check).
BOSS2.kommission.dialekt={
 "Ich kriege seit drei Tagen immer schlechter Luft.":"Isch krieg seit drei Daach immer schlechder Luft.",
 "Drei. Und letzte Nacht habe ich im Sessel geschlafen.":"Drei. Un letschd Nacht hab isch im Sessel gschlofe.",
 "Die Knöchel, ja. Die Schuhe gehen abends kaum noch zu.":"Die Knechel, jo. Die Schuh gehn owends kaum noch zu.",
 "Ich muss nachts dreimal raus. Appetit habe ich kaum.":"Isch muss nachts dreimol raus. Appetit hab isch kaum.",
 "Gegen Penicillin. Da kriege ich Ausschlag.":"Geesche Penicillin. Do krieg isch Ausschlag.",
 "Mein Vater ist mit achtundfünfzig am Herzinfarkt gestorben.":"Moin Vadder is mit achtunfuffzisch am Herzinfarkt gschdorbe."};

// ---------------------------------------------------------------- lines (I5 P2–P6; BOSX intro/win/lose are shown from BOSSES[id] and win where both exist)
BOSS2.hexe.lines={
 intro:[["H","Komm herein, Kind. Mein Ofen ist warm. Ich nehme nur die Artikel. Und dann dich.","Come in, child. My oven is warm. I only take the articles. And then you."],
        ["M","Jeder Fehler kommt in eines ihrer Gläser – mit Ihrem falschen Artikel auf dem Etikett. Holen Sie das Wort zurück, dann zerbricht das Glas. Machen Sie denselben Fehler zweimal, dann kostet es eine Kerze.","Every mistake goes into one of her jars — with your wrong article on the label. Take the word back and the jar breaks. Make the same mistake twice and it costs a candle.","Jeder Fehler kommt in eines ihrer Gläser – mit deinem falschen Artikel auf dem Etikett. Hol das Wort zurück, dann zerbricht das Glas. Machst du denselben Fehler zweimal, kostet es eine Kerze."]],
 phase:[
  {h:["H","Der, die, das – wer kennt das? Schnell, Kind. Der Ofen wartet nicht.","Der, die, das — who knows which? Quick, child. The oven does not wait."],
   m:["M","Drücken Sie das richtige Siegel auf jedes Nomen. Acht Treffer.","Press the right seal on each noun. Eight hits.","Drück das richtige Siegel auf jedes Nomen. Acht Treffer."]},
  {h:["H","Jetzt koche ich. Ich lese mein Rezept. Aber wo sind die Artikel? Oh. In meiner Tasche.","Now I cook. I read my recipe. But where are the articles? Oh. In my pocket."],
   m:["M","Der Mann – den Mann. Nur der Mann ändert sich. Das wissen Sie. Zeigen Sie es.","Der Mann — den Mann. Only the masculine changes. You know that. Show it.","Der Mann – den Mann. Nur der Mann ändert sich. Das weißt du. Zeig es."]},
  {h:["H","Ein Kind ist gut. Zwei Kinder sind besser. Was kommt aus dem Ofen? Zähl!","One child is good. Two children are better. What comes out of the oven? Count!"],
   m:["M","Plural. Fünf Formen, kein System, sagen die Faulen. Es gibt ein System. Sie haben es gelernt.","Plural. Five forms, no system, say the lazy. There is a system. You have learnt it.","Plural. Fünf Formen, kein System, sagen die Faulen. Es gibt ein System. Du hast es gelernt."]}],
 tele:{steal:["H","Die Farben gehören mir!","The colours are mine!"],swap:["H","Ich lese vor. Hör gut zu. Ein Wort ist falsch.","I read aloud. Listen well. One word is wrong."],throwback:["H","Das kennst du schon. Aber kennst du zwei?","You know this one. But do you know two of them?"]},
 hit:[["H","Au! Das Siegel brennt.","Ow! The seal burns."],["H","Nicht schlecht für ein Kind.","Not bad for a child."],["N","A jar cracks on the shelf."],["M","Richtig. Weiter.","Correct. Go on.","Richtig. Weiter."]],
 miss:{genus:[["H","Falsch. Das Wort gehört jetzt mir. Es kommt in mein Glas.","Wrong. The word is mine now. It goes into my jar."],["H","Knusper, knusper. Dein Artikel ist verbrannt.","Nibble, nibble. Your article is burnt."]],
       akk:[["H","Der Mann? Ich esse den Mann. Mit n.","Der Mann? I eat den Mann. With an n."],["H","Wer macht es? Was nimmt er? Du weißt es nicht.","Who does it? What does he take? You do not know."]],
       nom:[["H","Nach „ist“ kommt kein Akkusativ, Kind.","No accusative after 'ist', child."]],
       kein:[["H","Kein, keine, keinen. Du hast keine Ahnung.","Kein, keine, keinen. You have no idea."]],
       dat:[["H","Mit dem Löffel. Dem. Ich koche seit 300 Jahren.","Mit dem Löffel. Dem. I have been cooking for 300 years."]],
       plural:[["H","Kinds? Hier ist nicht England.","Kinds? This is not England."],["H","Ein Wort zu wenig für meinen Ofen.","One word too few for my oven."]]},
 second:[["H","Zweimal derselbe Fehler. Eine Kerze für mich.","The same mistake twice. One candle for me."],["M","Sie haben die Antwort gesehen und nicht gelesen. Das ist teuer.","You saw the answer and did not read it. That is expensive.","Du hast die Antwort gesehen und nicht gelesen. Das ist teuer."]],
 lift:[["H","Nein! Mein Glas!","No! My jar!"],["M","Fluch gebrochen. Das Wort gehört wieder Ihnen. Doppelter Treffer.","Curse broken. The word is yours again. Double hit.","Fluch gebrochen. Das Wort gehört wieder dir. Doppelter Treffer."]],
 lastCandle:["M","Eine Kerze. Lesen Sie jetzt jedes Wort zweimal. Ich warte.","One candle. Now read every word twice. I will wait.","Eine Kerze. Lies jetzt jedes Wort zweimal. Ich warte."],
 fin:[["H","Drei Gläser habe ich noch. Meine drei.","I still have three jars. My three."],["M","Ihre drei. Holen Sie sie.","Your three. Go and get them.","Deine drei. Hol sie dir."]],
 win:[["N","You say the last word with its article. The last jar breaks. She steps back, and the oven is behind her."],["H","Der Ofen … ist … heiß!","The oven … is … hot!"],["M","Der Ofen. Maskulin. Sie hat es bis zum Ende gewusst. Sie jetzt auch.","Der Ofen. Masculine. She knew it to the end. Now so do you.","Der Ofen. Maskulin. Sie hat es bis zum Ende gewusst. Du jetzt auch."]],
 lose:[["H","Die Tür ist zu. Deine Wörter bleiben bei mir.","The door is shut. Your words stay with me."],["M","Sie stehen noch in ihren Gläsern. Holen Sie sie in Ruhe – ohne Uhr. Dann kommen Sie wieder.","They are still in her jars. Take them back in peace — no clock. Then return.","Sie stehen noch in ihren Gläsern. Hol sie in Ruhe – ohne Uhr. Dann komm wieder."]]};
BOSS2.golem.lines={
 intro:[["M","Er besteht aus Ihren Sätzen. Ein richtiger Satz ist ein Befehl: Er gehorcht. Ein falscher Satz ist Lehm: Er wächst. Denselben Fehler zweimal – und es wird dunkler.","He is made of your sentences. A correct sentence is an order: he obeys. A wrong sentence is clay: he grows. The same mistake twice — and it gets darker.","Er besteht aus deinen Sätzen. Ein richtiger Satz ist ein Befehl: Er gehorcht. Ein falscher Satz ist Lehm: Er wächst. Denselben Fehler zweimal – und es wird dunkler."],
        ["G","Verb.","Verb."]],
 phase:[
  {g:["G","Platz. Zwei.","Place. Two."],m:["M","Das Verb steht auf Platz zwei. Immer. Was auf Platz eins steht, ist dem Verb egal.","The verb stands in place two. Always. What stands in place one, the verb does not care.","Das Verb steht auf Platz zwei. Immer. Was auf Platz eins steht, ist dem Verb egal."]},
  {g:["G","Zwei … Teile.","Two … parts."],m:["M","Jetzt hat das Verb zwei Teile. Ein Teil auf Platz zwei, ein Teil ganz am Ende. Dazwischen ist Platz für alles andere.","Now the verb has two parts. One in place two, one at the very end. Everything else fits in between.","Jetzt hat das Verb zwei Teile. Ein Teil auf Platz zwei, ein Teil ganz am Ende. Dazwischen ist Platz für alles andere."]},
  {g:["G","Weil. Dass. Wenn. Ob.","Because. That. If. Whether."],m:["M","Nach diesen vier Wörtern geht das Verb ans Ende. Und wenn der Nebensatz vorne steht, kommt das Verb sofort nach dem Komma.","After these four words the verb goes to the end. And when the clause stands in front, the verb comes straight after the comma.","Nach diesen vier Wörtern geht das Verb ans Ende. Und wenn der Nebensatz vorne steht, kommt das Verb sofort nach dem Komma."]}],
 tele:{stamp:["N","He lifts his foot. One of your sentences is shaking."],mauer:["N","He turns the wall around. Your clause is now at the front."]},
 hit:[["G","Ich … gehorche.","I … obey."],["N","A letter on his forehead flickers."],["M","Richtig gebaut.","Built correctly.","Richtig gebaut."]],
 miss:{v2:[["G","Verb … Platz … zwei.","Verb … place … two."],["M","Sie haben zwei Dinge vor das Verb gestellt. Er hat beide gegessen.","You put two things before the verb. He ate both.","Du hast zwei Dinge vor das Verb gestellt. Er hat beide gegessen."]],
       klammer:[["G","Ende. Verb. Ende.","End. Verb. End."],["M","Der zweite Teil gehört ans Ende. Nicht in die Mitte.","The second part belongs at the end. Not in the middle.","Der zweite Teil gehört ans Ende. Nicht in die Mitte."]],
       trennbar:[["G","Auf. Am. Ende.","Auf. At. The end."]],
       perfekt:[["G","Ge-. Ge-. Ge-.","Ge-. Ge-. Ge-."]],
       neben:[["G","Weil … Verb … Ende.","Because … verb … end."],["M","Das war die englische Wortstellung. Wir sind in Prag.","That was English word order. We are in Prague.","Das war die englische Wortstellung. Wir sind in Prag."]],
       kasus:[["G","Dem. Nicht den.","Dem. Not den."]]},
 grow:["N","He grows. Your wrong sentence is now part of him: you can read it in his chest."],
 second:[["G","Wieder.","Again."],["M","Derselbe Ziegel, zweimal falsch. Eine Kerze.","The same brick, wrong twice. One candle.","Derselbe Ziegel, zweimal falsch. Eine Kerze."]],
 lift:[["N","The wrong row crumbles. He is smaller than before."],["M","Sie haben Ihren eigenen Fehler repariert. Das zählt doppelt.","You repaired your own mistake. That counts double.","Du hast deinen eigenen Fehler repariert. Das zählt doppelt."]],
 lastCandle:["M","Eine Kerze. Bauen Sie langsam. Die Uhr ist großzügiger, als Sie denken.","One candle. Build slowly. The clock is more generous than you think.","Eine Kerze. Bau langsam. Die Uhr ist großzügiger, als du denkst."],
 fin:[["N","On his forehead only one letter is left. Below it, a paragraph in your handwriting."],["M","Ein Wort ist falsch. Nur eins. Finden Sie es, dann verlischt der letzte Buchstabe.","One word is wrong. Only one. Find it, and the last letter goes out.","Ein Wort ist falsch. Nur eins. Finde es, dann verlischt der letzte Buchstabe."]],
 win:[["G","Danke.","Thank you."],["M","Er hat sich bedankt. Das Verb stand auf Platz eins, weil es ein Satz mit einem Wort war. Selbst er kann es.","He said thank you. The verb stood in first place because the sentence had one word. Even he can do it.","Er hat sich bedankt. Das Verb stand auf Platz eins, weil es ein Satz mit einem Wort war. Selbst er kann es."]],
 lose:[["N","He pushes you out of the café, gently, the way one moves a chair."],["M","Ihre falschen Sätze stecken noch in ihm. Tragen Sie die Mauer ab, Ziegel für Ziegel. Dann kommen Sie wieder.","Your wrong sentences are still inside him. Take the wall down, brick by brick. Then come back.","Deine falschen Sätze stecken noch in ihm. Trag die Mauer ab, Ziegel für Ziegel. Dann komm wieder."]]};
BOSS2.pudel.lines={
 intro:[["P","Ich bin der Geist, der stets verneint. Sagen Sie einen Satz – ich sage: falsch. Sagen Sie ihn anders – ich bin schon ein anderer.","I am the spirit that always negates. Say a sentence — I say: wrong. Say it differently — I am already someone else."],
        ["M","Er war einmal meine Lieblingsgestalt. Achten Sie auf seine Form: Jede Form verlangt eine andere Grammatik. Derselbe Gedanke, fünf Kleider.","He was once my favourite shape. Watch his form: each form demands a different grammar. The same thought, five costumes.","Er war einmal meine Lieblingsgestalt. Achte auf seine Form: Jede Form verlangt eine andere Grammatik. Derselbe Gedanke, fünf Kleider."]],
 phase:[
  {p:["P","Gestern. Erzählen Sie mir von gestern. Schriftlich – und dann so, wie man spricht.","Yesterday. Tell me about yesterday. As one writes it — and then as one says it."],
   m:["M","Schwarzer Pudel: Präteritum. Nasser Pudel: Perfekt. Mehr ist es nicht. Noch nicht.","Black poodle: preterite. Wet poodle: perfect. That is all. For now.","Schwarzer Pudel: Präteritum. Nasser Pudel: Perfekt. Mehr ist es nicht. Noch nicht."]},
  {p:["P","Wer es getan hat, interessiert mich nicht mehr. Mich interessiert, was getan wird.","I no longer care who did it. I care what is being done."],
   m:["M","Passiv. Das Objekt wird zum Subjekt. Und wenn es kein Objekt gibt? Dann sagen Sie das.","Passive. The object becomes the subject. And if there is no object? Then say so.","Passiv. Das Objekt wird zum Subjekt. Und wenn es kein Objekt gibt? Dann sag das."]},
  {p:["P","Jetzt reden wir über das, was andere sagen. Und über das, was nicht ist.","Now we speak of what others say. And of what is not."],
   m:["M","Der Scholar zitiert: Konjunktiv I. Der Nebel träumt: Konjunktiv II. Verwechseln Sie die beiden nicht – er wartet darauf.","The scholar quotes: subjunctive I. The mist dreams: subjunctive II. Do not confuse them — he is waiting for it.","Der Scholar zitiert: Konjunktiv I. Der Nebel träumt: Konjunktiv II. Verwechsle die beiden nicht – er wartet darauf."]}],
 tele:{shift:["P","Sie dachten, Sie kennen mich?","You thought you knew me?"],shadow:["P","Das haben Sie gesagt. Ich habe es aufgehoben.","You said this. I kept it."]},
 hit:[["P","Hm. Das kann ich nicht verneinen.","Hm. That I cannot negate."],["M","Richtig – in dieser Gestalt.","Correct — in this shape.","Richtig – in dieser Gestalt."]],
 miss:{praet:[["P","Sie sagten es schwach. Das Verb ist stark.","You said it weak. The verb is strong."]],
       perf:[["P","Haben oder sein – das ist hier die Frage.","To have or to be — that is the question here."]],
       passiv:[["P","Wer wird hier untersucht? Sie haben das Subjekt verloren.","Who is being examined here? You have lost the subject."]],
       indirekt:[["P","„Ich“? Sie zitieren, Doktor. Sie sind nicht der Patient.","'I'? You are quoting, Doctor. You are not the patient."]],
       konj2:[["P","Das war Wirklichkeit. Ich wollte einen Traum.","That was reality. I wanted a dream."]]},
 echo:["P","Sie sagten: „{GIVEN}“","You said: '{GIVEN}'"],
 second:[["P","Zweimal. Jetzt gehört der Satz mir – und eine Kerze dazu.","Twice. Now the sentence is mine — and a candle with it."]],
 lift:[["P","Den nehmen Sie mir also wieder weg.","So you take that one back from me."],["M","Ihren eigenen Fehler korrigiert. Doppelter Treffer.","Your own mistake corrected. Double hit.","Deinen eigenen Fehler korrigiert. Doppelter Treffer."]],
 lastCandle:["M","Eine Kerze. Sehen Sie zuerst auf die Gestalt, dann auf den Satz.","One candle. Look at the shape first, then at the sentence.","Eine Kerze. Sieh zuerst auf die Gestalt, dann auf den Satz."],
 fin:[["P","Und jetzt sehen Sie mich an. Ich bestehe aus Ihren Fehlern. Drei habe ich mitgebracht.","And now look at me. I am made of your mistakes. I brought three."],["M","Das also ist des Pudels Kern. Widersprechen Sie ihm.","So that is the poodle's core. Contradict him.","Das also ist des Pudels Kern. Widersprich ihm."]],
 win:[["P","Wenn ich noch einen Fehler hätte, würde ich bleiben.","If I had one more mistake, I would stay."],["M","Konjunktiv II. Sogar im Verschwinden korrekt. Von wem er das wohl hat.","Subjunctive II. Correct even while vanishing. I wonder where he got that.","Konjunktiv II. Sogar im Verschwinden korrekt. Von wem er das wohl hat."]],
 lose:[["P","Ich verneine Sie. Für heute.","I negate you. For today."],["M","Er hat Ihre Sätze behalten. Holen Sie sie zurück: Widersprechen Sie ihm, Satz für Satz, ohne Uhr.","He kept your sentences. Take them back: contradict him, sentence by sentence, without a clock.","Er hat deine Sätze behalten. Hol sie zurück: Widersprich ihm, Satz für Satz, ohne Uhr."]]};
BOSS2.caligari.lines={
 intro:[["M","Er wird Ihnen nichts Unbekanntes zeigen. Nur Bekanntes, leicht verschoben. Je sicherer Sie sich fühlen, desto schiefer steht der Raum. Widersprechen Sie ihm – höflich, aber sofort.","He will show you nothing unknown. Only the familiar, slightly shifted. The surer you feel, the more the room leans. Contradict him — politely, but at once.","Er wird dir nichts Unbekanntes zeigen. Nur Bekanntes, leicht verschoben. Je sicherer du dich fühlst, desto schiefer steht der Raum. Widersprich ihm – höflich, aber sofort."]],
 phase:[
  {c:["C","Wörter, die Sie aus dem Englischen kennen! Alte Freunde! Vertrauen Sie ihnen.","Words you know from English! Old friends! Trust them."],
   m:["M","Falsche Freunde. Sie sehen aus wie Verwandte und lügen wie Zeugen.","False friends. They look like relatives and lie like witnesses.","Falsche Freunde. Sie sehen aus wie Verwandte und lügen wie Zeugen."]},
  {c:["C","Zwar, aber, trotzdem, obwohl – kleine Wörter. Wer achtet schon auf kleine Wörter?","Zwar, aber, trotzdem, obwohl — little words. Who pays attention to little words?"],
   m:["M","Jedes dieser Wörter entscheidet, wo das Verb steht. Achten Sie auf die kleinen.","Each of these words decides where the verb stands. Watch the little ones.","Jedes dieser Wörter entscheidet, wo das Verb steht. Achte auf die kleinen."]},
  {c:["C","Meine Patienten sprechen Amtsdeutsch im Schlaf. Hören Sie: Es klingt wichtig. Also ist es richtig.","My patients speak officialese in their sleep. Listen: it sounds important. Therefore it is right."],
   m:["M","Es klingt wichtig und enthält je einen Fehler. Wecken Sie die Leute. Ein Griff an die richtige Stelle genügt.","It sounds important and contains one error each. Wake these people. One touch in the right place is enough.","Es klingt wichtig und enthält je einen Fehler. Weck die Leute. Ein Griff an die richtige Stelle genügt."]}],
 tele:{sugg:["C","Sehen Sie mir in die Augen. Ich sage Ihnen jetzt eine Regel.","Look into my eyes. I shall now tell you a rule."],diktat:["C","Zum Diktat!","Take dictation!"]},
 hit:[["C","Ein Zufall.","A coincidence."],["N","Einer der Schlafwandler öffnet die Augen.","One of the sleepwalkers opens his eyes."],["M","Wach geblieben.","You stayed awake.","Wach geblieben."]],
 miss:{ff:[["C","Sehen Sie? Es klang doch so vertraut.","You see? It sounded so familiar."],["M","Das war Englisch in deutscher Uniform.","That was English in a German uniform.","Das war Englisch in deutscher Uniform."]],
       konn:[["C","Die Wände neigen sich. Wie Ihr Satzbau.","The walls lean. Like your syntax."]],
       neben:[["C","Das Verb, mein Herr – es schlafwandelt.","The verb, sir — it is sleepwalking."]],
       nominal:[["C","Nominalstil, nicht Gestammel.","Nominal style, not stammering."]],
       koll:[["C","Man kann vieles machen. Eine Entscheidung nicht.","One can 'make' many things. Not a decision."]],
       passiv:[["C","Vorgang oder Zustand? Für mich ist alles Zustand.","Process or state? To me everything is a state."]]},
 trance:[["N","Der Raum neigt sich. Eine vierte Antwort steht auf einmal da.","The room leans. A fourth answer is suddenly there."],["C","Ich empfehle Ihnen diese Antwort.","I recommend this answer to you."],["N","Sie schlafen einen Augenblick. Eine Kerze ist aus.","You sleep for a moment. A candle is out."]],
 second:[["C","Zweimal dasselbe. Sie gehören schon fast zu meinem Kabinett.","The same thing twice. You almost belong to my cabinet already."]],
 lift:[["N","Der Raum richtet sich ein Stück auf.","The room straightens a little."],["M","Sie haben ihm widersprochen. Doppelter Treffer.","You contradicted him. Double hit.","Du hast ihm widersprochen. Doppelter Treffer."]],
 lastCandle:["M","Eine Kerze. Wenn eine Antwort sofort richtig klingt, lesen Sie die anderen zweimal.","One candle. If an answer sounds right at once, read the others twice.","Eine Kerze. Wenn eine Antwort sofort richtig klingt, lies die anderen zweimal."],
 fin:[["N","Cesare öffnet die Augen und spricht – mit Ihren drei Fehlern.","Cesare opens his eyes and speaks — with your three mistakes."],["M","Wer hier der Direktor ist, entscheidet sich an drei Sätzen.","Who the director is here will be decided by three sentences.","Wer hier der Direktor ist, entscheidet sich an drei Sätzen."]],
 win:[["N","Cesare ist wach. Die Schlafwandler stehen im Halbkreis um Caligari.","Cesare is awake. The sleepwalkers stand in a half circle around Caligari."],["C","Das ist ein Irrtum. Ich bin der Direktor!","This is a mistake. I am the director!"],["M","„Direktor“ ist übrigens kein falscher Freund. Der hier schon.","'Direktor', by the way, is not a false friend. This one is.","„Direktor“ ist übrigens kein falscher Freund. Der hier schon."]],
 lose:[["C","Schlafen Sie, Herr Doktor. Im Schlaf spricht jeder fließend.","Sleep, Doctor. Everyone is fluent in his sleep."],["M","Sie sind eingeschlafen, weil es vertraut klang. Gehen Sie die Fehler wach noch einmal durch – in beiden Richtungen.","You fell asleep because it sounded familiar. Go through the mistakes again, awake — in both directions.","Du bist eingeschlafen, weil es vertraut klang. Geh die Fehler wach noch einmal durch – in beiden Richtungen."]]};
BOSS2.kommission.lines={
 intro:[["N","Drei Ärztinnen und Ärzte hinter einem Tisch. Auf dem Stuhl davor sitzt eine Frau von einundsiebzig Jahren mit einem Namensschild: „Simulationspatientin“. Sie spielt heute eine Frau mit Luftnot.","Three doctors behind a table. On the chair in front of them sits a woman of seventy-one with a name badge: 'simulated patient'. Today she is playing a woman who is short of breath."],
        ["M","Ich darf nicht mit hinein. Vierzig Kapitel lang habe ich Ihnen dazwischengeredet; jetzt werden andere Sie unterbrechen. Antworten Sie ihnen, und dann kehren Sie zu Ihrem Satz zurück. Mehr habe ich Ihnen nie beigebracht.","I am not allowed in. For forty chapters I talked over you; now others will interrupt you. Answer them, and then return to your sentence. I never taught you anything else.","Ich darf nicht mit hinein. Vierzig Kapitel lang habe ich dir dazwischengeredet; jetzt werden andere dich unterbrechen. Antworte ihnen, und dann kehr zu deinem Satz zurück. Mehr habe ich dir nie beigebracht."],
        ["V","Guten Tag, Herr Kollege. Sie haben zwanzig Minuten für die Anamnese. Bitte.","Good day, colleague. You have twenty minutes for the history. Please."]],
 phase:[
  {v:["V","Ihre Patientin ist Frau Brandt. Sprechen Sie mit ihr, nicht mit uns.","Your patient is Frau Brandt. Speak to her, not to us."]},
  {v:["V","Danke. Nun dokumentieren Sie, was Sie gehört haben. Die Patientin hat erzählt; der Brief berichtet.","Thank you. Now document what you heard. The patient told you; the letter reports."]},
  {v:["V","Stellen Sie uns die Patientin vor. Wir werden Fragen haben.","Present the patient to us. We shall have questions."]}],
 tele:{intr:["N","Frau Brandt hebt die Hand.","Frau Brandt raises her hand."],rueck:["N","Der Prüfer hält Ihr Blatt hoch und liest einen Satz vor.","The examiner holds up your sheet and reads a sentence aloud."],zwischen:["V","Einen Moment, Herr Kollege.","One moment, colleague."]},
 hit:[["N","Die Vorsitzende nickt kaum sichtbar.","The chair nods, barely visibly."],["N","Frau Brandt antwortet.","Frau Brandt answers."],["N","Ein Stift bleibt ruhig liegen.","A pen stays where it is."]],
 miss:{register:[["N","Frau Brandt sieht Sie an. „Wie bitte, Herr Doktor?“","Frau Brandt looks at you. 'Pardon, doctor?'"],["V","Die Patientin ist keine Kollegin.","The patient is not a colleague."]],
       kasus:[["N","Ein Prüfer schreibt ein einzelnes Wort auf.","An examiner writes down a single word."]],
       satzbau:[["N","Die Prüferin wiederholt Ihren Satz leise – richtig.","The examiner repeats your sentence quietly — correctly."]],
       koll:[["V","Das versteht man. Aber so sagt man es nicht.","One understands that. But that is not how one says it."]],
       fach:[["V","Im Brief bitte Fachsprache.","Technical language in the letter, please."]],
       konj1:[["V","Wer sagt das – Sie oder die Patientin? Der Konjunktiv sagt es uns.","Who says so — you or the patient? The subjunctive tells us."]],
       term:[["V","Das versteht die Patientin nicht.","The patient does not understand that."]],
       reaktion:[["N","Frau Brandt schweigt einen Moment. Dann stellt sie ihre Frage noch einmal.","Frau Brandt is silent for a moment. Then she asks her question again."]],
       praep:[["N","Ein Stift kratzt.","A pen scratches."]],
       endung:[["N","Ein Stift kratzt.","A pen scratches."]],
       brief:[["V","So steht es in keinem Arztbrief.","No doctor's letter says it like that."]]},
 unconvinced:["V","Die Kommission ist noch nicht überzeugt. Wir bleiben noch einen Augenblick bei diesem Teil.","The commission is not yet convinced. We shall stay with this part a moment longer."],
 second:[["V","Diesen Punkt hatten wir bereits.","We have had this point already."]],
 lift:[["N","Der Prüfer streicht eine Notiz wieder durch.","The examiner crosses a note out again."]],
 lastCandle:["M","(durch die Tür, leise) Lesen Sie alle drei Antworten zu Ende. Dann erst wählen.","(through the door, quietly) Read all three answers to the end. Only then choose.","(durch die Tür, leise) Lies alle drei Antworten zu Ende. Dann erst wählen."],
 fin:[["V","Jeder von uns hat noch eine Frage.","Each of us has one more question."]],
 win:[["N","Frau Brandt nimmt das Namensschild ab und nickt Ihnen zu.","Frau Brandt takes off her name badge and nods to you."]],
 lose:[["V","Wir sehen uns wieder. Sie wissen jetzt, in welchem Teil.","We shall meet again. You now know in which part."],["M","Sie sind in einem Raum durchgefallen, nicht in der Sprache. Üben Sie diesen Raum, ohne Uhr. Ich warte vor der Tür. Ich habe Zeit – seit ein paar Jahrtausenden.","You failed in one room, not in the language. Practise that room, without a clock. I shall wait outside the door. I have time — a few millennia of it.","Du bist in einem Raum durchgefallen, nicht in der Sprache. Übe diesen Raum, ohne Uhr. Ich warte vor der Tür. Ich habe Zeit – seit ein paar Jahrtausenden."]]};
