// ===== x_i8_lines.js · package i8 · texts of the pact economy (PLAN-I R7; I7 §7.1 MEPH7, §7.2 ZEUGNIS7, P1 NOTIZ, P2 IF_*, P1 punishments)
// Voice lines are [Sie, English, du]. Tokens: {n} {m} numbers, {w} a word or phrase. c_i8.js converts them for s5's MEPH2 ([sie,en,du,lv,flags]).
// Rules kept (BRIEF): Mephisto mocks German, laziness and excuses — never religion, origin or family. Nothing here is in Frau Brandt's voice (PLAN-I R1).
var MEPH7={
 back_short:[
  ["{n} Tage. Setzen Sie sich. Zehn Karten.","{n} days. Sit down. Ten cards.","{n} Tage. Setz dich. Zehn Karten."],
  ["Sie waren weg. Ich sage heute nichts dazu. Zehn Karten.","You were gone. I'll say nothing about it today. Ten cards.","Du warst weg. Ich sage heute nichts dazu. Zehn Karten."],
  ["Da sind Sie. Fangen wir klein an. Klein können Sie.","There you are. Let's start small. Small you can manage.","Da bist du. Fangen wir klein an. Klein kannst du."]],
 back_week:[
  ["{n} Tage. Ich bin nicht wütend. Ich bin enttäuscht. Das ist schlimmer.","{n} days. I'm not angry. I'm disappointed. That is worse.","{n} Tage. Ich bin nicht wütend. Ich bin enttäuscht. Das ist schlimmer."],
  ["{n} Tage ohne ein Wort. Heute verlange ich zehn Karten. Mehr trauen wir Ihnen beide nicht zu.","{n} days without a word. Today I ask for ten cards. Neither of us trusts you with more.","{n} Tage ohne ein Wort. Heute verlange ich zehn Karten. Mehr trauen wir dir beide nicht zu."],
  ["Ich habe jeden Abend Ihre Karten gemischt. Für niemanden. Zehn davon – jetzt.","I shuffled your cards every evening. For no one. Ten of them — now.","Ich habe jeden Abend deine Karten gemischt. Für niemanden. Zehn davon – jetzt."]],
 back_long:[
  ["{n} Tage. Bevor ich etwas sage: zwanzig alte Karten. Ich will wissen, was noch da ist.","{n} days. Before I say anything: twenty old cards. I want to know what is still there.","{n} Tage. Bevor ich etwas sage: zwanzig alte Karten. Ich will wissen, was noch da ist."],
  ["{n} Prozent. Es ist weniger geworden. Es ist nicht weg. Morgen holen wir es zurück.","{n} per cent. There is less of it. It is not gone. Tomorrow we fetch it back.","{n} Prozent. Es ist weniger geworden. Es ist nicht weg. Morgen holen wir es zurück."],
  ["{n} Prozent sind geblieben. Ihr Kopf ist treuer als Sie. Schämen Sie sich – und machen Sie weiter.","{n} per cent stayed. Your head is more loyal than you are. Be ashamed — and carry on.","{n} Prozent sind geblieben. Dein Kopf ist treuer als du. Schäm dich – und mach weiter."]],
 back_done:[
  ["Zehn Karten. Das war wenig, und es war genug. Morgen: zwanzig.","Ten cards. It was little and it was enough. Tomorrow: twenty.","Zehn Karten. Das war wenig, und es war genug. Morgen: zwanzig."],
  ["Sie sind zurück. Notiert. Gehen Sie, bevor ich etwas Freundliches sage.","You're back. Noted. Go, before I say something kind.","Du bist zurück. Notiert. Geh, bevor ich etwas Freundliches sage."],
  ["Der erste Tag ist der schwerste. Den haben Sie jetzt hinter sich. Den zweiten schulden Sie mir.","The first day is the hardest. That one is behind you now. The second you owe me.","Der erste Tag ist der schwerste. Den hast du jetzt hinter dir. Den zweiten schuldest du mir."]],
 excuse:[
  ["Schon wieder ein neuer Dienstplan. Ihr Krankenhaus plant offenbar mit Würfeln.","Yet another new rota. Your hospital evidently plans with dice.","Schon wieder ein neuer Dienstplan. Dein Krankenhaus plant offenbar mit Würfeln."],
  ["Dreimal getauscht in einer Woche. Ich trage es ein. Ich glaube es nicht, aber ich trage es ein.","Swapped three times in one week. I'll enter it. I don't believe it, but I'll enter it.","Dreimal getauscht in einer Woche. Ich trage es ein. Ich glaube es nicht, aber ich trage es ein."],
  ["Zwei Wochen „Mindestens“. Sie wetten gegen sich selbst und nennen es Vorsicht.","Two weeks of 'at least'. You are betting against yourself and calling it caution.","Zwei Wochen „Mindestens“. Du wettest gegen dich selbst und nennst es Vorsicht."],
  ["Kein Dienst, keine Ausrede. Ehrlich. Das sehe ich selten. Der Schuldschein bleibt.","No shift, no excuse. Honest. I rarely see that. The IOU stands.","Kein Dienst, keine Ausrede. Ehrlich. Das sehe ich selten. Der Schuldschein bleibt."]],
 avoid:[
  ["Übersprungen: {w}. Schon wieder. Sie laufen nicht vor mir weg. Sie laufen vor genau dieser einen Sache weg.","Skipped: {w}. Again. You're not running from me. You're running from exactly this one thing.","Übersprungen: {w}. Schon wieder. Du läufst nicht vor mir weg. Du läufst vor genau dieser einen Sache weg."],
  ["Sie überspringen, was Sie nicht können. Ein Chirurg, der nur die leichten Schnitte macht.","You skip what you can't do. A surgeon who makes only the easy cuts.","Du überspringst, was du nicht kannst. Ein Chirurg, der nur die leichten Schnitte macht."],
  ["Der Schuldschein liegt seit {n} Tagen hier. Mit Schuldnern rede ich nicht. Zehn Karten.","The IOU has been lying here for {n} days. I don't talk to debtors. Ten cards.","Der Schuldschein liegt seit {n} Tagen hier. Mit Schuldnern rede ich nicht. Zehn Karten."],
  ["Zehn Karten. Dann reden wir wieder.","Ten cards. Then we talk again.","Zehn Karten. Dann reden wir wieder."],
  ["Ich warte nicht. Ich zähle.","I am not waiting. I am counting.","Ich warte nicht. Ich zähle."]],
 sloppy_fast:[
  ["{n} Sekunden. So schnell denkt niemand. Sie haben geraten.","{n} seconds. Nobody thinks that fast. You guessed.","{n} Sekunden. So schnell denkt niemand. Du hast geraten."],
  ["Sie tippen, bevor Sie lesen. Am Bett nennt man das einen Behandlungsfehler.","You tap before you read. At the bedside that is called malpractice.","Du tippst, bevor du liest. Am Bett nennt man das einen Behandlungsfehler."]],
 sloppy_repeat:[
  ["Derselbe Fehler, zum {n}. Mal. Ihr Schatten kennt ihn schon beim Namen.","The same mistake, for the {n}th time. Your shadow already knows it by name.","Derselbe Fehler, zum {n}. Mal. Dein Schatten kennt ihn schon beim Namen."],
  ["Das haben Sie schon {n}-mal vergessen. Beim nächsten Mal schreibe ich es Ihnen auf die Hand.","You have forgotten this {n} times already. Next time I'll write it on your hand.","Das hast du schon {n}-mal vergessen. Beim nächsten Mal schreibe ich es dir auf die Hand."]],
 sloppy_old:[
  ["Das konnten Sie seit Wochen. Was man hat, muss man halten.","You have known that for weeks. What one has, one must hold.","Das konntest du seit Wochen. Was man hat, muss man halten."],
  ["Ein altes Wort verloren. Das ärgert mich mehr als zehn neue Fehler.","An old word lost. That annoys me more than ten new mistakes.","Ein altes Wort verloren. Das ärgert mich mehr als zehn neue Fehler."]],
 fail_honest:[
  ["Neu. Falsch. Normal. Noch einmal.","New. Wrong. Normal. Again.","Neu. Falsch. Normal. Noch einmal."],
  ["Das können Sie noch nicht wissen. Beim dritten Mal erwarte ich es.","You can't know that yet. The third time I expect it.","Das kannst du noch nicht wissen. Beim dritten Mal erwarte ich es."],
  ["Fehler bei Neuem zähle ich nicht. Ich zähle erst, wenn Sie es besser wissen.","I don't count mistakes on new things. I start counting once you know better.","Fehler bei Neuem zähle ich nicht. Ich zähle erst, wenn du es besser weißt."],
  ["Sie haben nachgedacht und falsch gelegen. Das ist mir lieber als geraten und richtig.","You thought and were wrong. I prefer that to guessed and right.","Du hast nachgedacht und falsch gelegen. Das ist mir lieber als geraten und richtig."],
  ["Schwer, ja. Deshalb steht es hier. Leichtes brauchen Sie nicht von mir.","Hard, yes. That is why it is here. Easy things you don't need from me.","Schwer, ja. Deshalb steht es hier. Leichtes brauchst du nicht von mir."]],
 grudge:[
  ["{n} Wörter sitzen heute fest. Ich habe daran gerüttelt. Sie halten.","{n} words are fixed today. I shook them. They hold.","{n} Wörter sitzen heute fest. Ich habe daran gerüttelt. Sie halten."],
  ["„{w}“. Nach {n} Fehlern. Ich hatte das Wort schon abgeschrieben. Sie offenbar nicht.","'{w}'. After {n} mistakes. I had already written that word off. You evidently had not.","„{w}“. Nach {n} Fehlern. Ich hatte das Wort schon abgeschrieben. Du offenbar nicht."],
  ["Zwanzig hintereinander. Ich habe nichts zu sagen. Genießen Sie das. Es kommt selten vor.","Twenty in a row. I have nothing to say. Enjoy that. It rarely happens.","Zwanzig hintereinander. Ich habe nichts zu sagen. Genieß das. Es kommt selten vor."],
  ["{n} Prozent. Das ist kein Glück mehr. Glück kann ich riechen.","{n} per cent. That is no longer luck. I can smell luck.","{n} Prozent. Das ist kein Glück mehr. Glück kann ich riechen."],
  ["Ich habe Ihren Text dreimal gelesen. Ich wollte einen Fehler finden. Lassen wir das.","I read your text three times. I wanted to find a mistake. Let's leave it.","Ich habe deinen Text dreimal gelesen. Ich wollte einen Fehler finden. Lassen wir das."],
  ["Das können Sie jetzt. Ich schreibe es ins Haben. Ungern, aber leserlich.","You can do that now. I am entering it under credit. Reluctantly, but legibly.","Das kannst du jetzt. Ich schreibe es ins Haben. Ungern, aber leserlich."],
  ["Vor dreißig Tagen: {n} Wörter. Heute: {m}. Ich rechne nicht gern zu Ihren Gunsten. Es stimmt trotzdem.","Thirty days ago: {n} words. Today: {m}. I don't like reckoning in your favour. It is still correct.","Vor dreißig Tagen: {n} Wörter. Heute: {m}. Ich rechne nicht gern zu deinen Gunsten. Es stimmt trotzdem."],
  ["Sauber. Sagen Sie jetzt nichts. Sie machen es sonst kaputt.","Clean. Say nothing now. You will only spoil it.","Sauber. Sag jetzt nichts. Du machst es sonst kaputt."]],
 crack:[
  ["(leise) Das war gut. Nicht „gut für Sie“. Gut.","(quietly) That was good. Not 'good for you'. Good.","(leise) Das war gut. Nicht „gut für dich“. Gut."],
  ["(leise) Ich hatte Bessere als Sie. Sie sind alle gegangen. Sie sind noch da.","(quietly) I have had better ones than you. They all left. You are still here.","(leise) Ich hatte Bessere als dich. Sie sind alle gegangen. Du bist noch da."],
  ["(leise) Frau Brandt wird Sie verstehen. Das weiß ich seit heute.","(quietly) Frau Brandt will understand you. I have known that since today.","(leise) Frau Brandt wird dich verstehen. Das weiß ich seit heute."]],
 crack_early:[
  ["Das war beinahe – nein. Ich habe nichts gesagt. Weiter.","That was almost — no. I said nothing. Next.","Das war beinahe – nein. Ich habe nichts gesagt. Weiter."],
  ["Für einen Moment dachte ich: Aus dem wird etwas. Der Moment ist vorbei. Weiter.","For a moment I thought: he'll amount to something. The moment has passed. Next.","Für einen Moment dachte ich: Aus dem wird etwas. Der Moment ist vorbei. Weiter."]],
 wager_g:[
  ["Ich strafe Sie nicht aus Bosheit. Ihre Seele ist mein Eigentum. Mein Eigentum lasse ich nicht verkommen.","I don't punish you out of malice. Your soul is my property. I don't let my property go to ruin.","Ich strafe dich nicht aus Bosheit. Deine Seele ist mein Eigentum. Mein Eigentum lasse ich nicht verkommen."],
  ["Ein Schuldschein ist kein Urteil. Er ist eine Rechnung. Rechnungen kann man bezahlen.","An IOU is not a verdict. It is a bill. Bills can be paid.","Ein Schuldschein ist kein Urteil. Er ist eine Rechnung. Rechnungen kann man bezahlen."]],
 wager_i:[
  ["Ich habe in Sie investiert. Wer investiert, will keinen Bankrott sehen. Zahlen Sie.","I have invested in you. An investor does not want to see a bankruptcy. Pay.","Ich habe in dich investiert. Wer investiert, will keinen Bankrott sehen. Zahl."],
  ["Glauben Sie, ich schreibe gern Schuldscheine? … Doch. Aber ich verbrenne sie noch lieber.","Do you think I enjoy writing IOUs? … I do. But I like burning them even more.","Glaubst du, ich schreibe gern Schuldscheine? … Doch. Aber ich verbrenne sie noch lieber."]],
 wager_s:[
  ["Ich habe auf Sie gesetzt. Fragen Sie nicht, bei wem. Fragen Sie nicht, auf welches Ende.","I have placed a bet on you. Don't ask with whom. Don't ask on which ending.","Ich habe auf dich gesetzt. Frag nicht, bei wem. Frag nicht, auf welches Ende."],
  ["Jeder Tag, an dem Sie fehlen, kostet mich mehr als Sie. Das sollen Sie nicht verstehen. Noch nicht.","Every day you miss costs me more than it costs you. You are not meant to understand that. Not yet.","Jeder Tag, an dem du fehlst, kostet mich mehr als dich. Das sollst du nicht verstehen. Noch nicht."]],
 klausel:[
  ["Ihre Klausel, Ihre Schrift, Ihre Strafe. Diesmal können Sie mir nichts vorwerfen.","Your clause, your hand, your punishment. This time you can't blame me for anything.","Deine Klausel, deine Schrift, deine Strafe. Diesmal kannst du mir nichts vorwerfen."],
  ["Besiegelt. Ich habe nichts verlangt. Das haben Sie ganz allein getan.","Sealed. I demanded nothing. You did that all by yourself.","Besiegelt. Ich habe nichts verlangt. Das hast du ganz allein getan."],
  ["Gehalten. {n} von {m}. Ich zahle. Ungern, pünktlich und vollständig.","Kept. {n} of {m}. I pay. Reluctantly, on time and in full.","Gehalten. {n} von {m}. Ich zahle. Ungern, pünktlich und vollständig."],
  ["Sie haben sich selbst etwas versprochen und es gehalten. Das ist seltener als gutes Latein.","You promised yourself something and kept it. That is rarer than good Latin.","Du hast dir selbst etwas versprochen und es gehalten. Das ist seltener als gutes Latein."],
  ["Gebrochen. {n} von {m}. Die Strafe haben Sie gewählt, nicht ich. Ich sehe nur zu.","Broken. {n} of {m}. You chose the punishment, not I. I only watch.","Gebrochen. {n} von {m}. Die Strafe hast du gewählt, nicht ich. Ich sehe nur zu."],
  ["Eine Woche Pause. Eingetragen. Werden Sie gesund – oder braun. Am Montag gehören Sie wieder mir.","A week off. Entered. Get well — or get a tan. On Monday you are mine again.","Eine Woche Pause. Eingetragen. Werd gesund – oder braun. Am Montag gehörst du wieder mir."],
  ["Mittwoch, und keine Klausel. Ich habe für Sie unterschrieben: „Mindestens“. Ihre Schrift war leicht zu fälschen.","Wednesday, and no clause. I signed for you: 'at least'. Your hand was easy to forge.","Mittwoch, und keine Klausel. Ich habe für dich unterschrieben: „Mindestens“. Deine Schrift war leicht zu fälschen."]],
 shift:[
  ["Dienst. Ihr Plan, nicht meiner: {w}. Fünf Minuten.","Shift. Your plan, not mine: {w}. Five minutes.","Dienst. Dein Plan, nicht meiner: {w}. Fünf Minuten."],
  ["Sie haben es selbst aufgeschrieben: {w}. Ich lese nur vor.","You wrote it down yourself: {w}. I am only reading it out.","Du hast es selbst aufgeschrieben: {w}. Ich lese nur vor."],
  ["Eine Runde. Noch zwei, dann zählt der Tag.","One round. Two more and the day counts.","Eine Runde. Noch zwei, dann zählt der Tag."],
  ["Drei Runden nach einem Dienst. Andere schaffen das nicht nach einem Urlaub.","Three rounds after a shift. Others can't manage that after a holiday.","Drei Runden nach einem Dienst. Andere schaffen das nicht nach einem Urlaub."],
  ["Es ist spät. Zehn Karten, dann schlafen. Im Schlaf arbeitet Ihr Kopf für mich weiter.","It is late. Ten cards, then sleep. In your sleep your head goes on working for me.","Es ist spät. Zehn Karten, dann schlafen. Im Schlaf arbeitet dein Kopf für mich weiter."],
  ["Notration. Der Tag zählt nicht. Aber er ist nicht leer, und leere Tage sind die teuren.","Emergency ration. The day does not count. But it is not empty, and empty days are the expensive ones.","Notration. Der Tag zählt nicht. Aber er ist nicht leer, und leere Tage sind die teuren."]],
 feierabend:[
  ["Genug für heute. Das sage ich, nicht Sie. Feierabend.","Enough for today. I say so, not you. Day's end.","Genug für heute. Das sage ich, nicht du. Feierabend."],
  ["Heute konnten Sie etwas, das Sie gestern nicht konnten. Mehr verlange ich von einem Tag nicht.","Today you could do something you couldn't do yesterday. I ask no more of one day.","Heute konntest du etwas, das du gestern nicht konntest. Mehr verlange ich von einem Tag nicht."],
  ["Morgen: {w}. Mehr müssen Sie heute Nacht nicht wissen.","Tomorrow: {w}. That is all you need to know tonight.","Morgen: {w}. Mehr musst du heute Nacht nicht wissen."],
  ["Die Tür ist zu. Wer jetzt noch lernt, tut es freiwillig. Ich sehe weg.","The door is shut. Whoever studies now does it of his own free will. I am looking away.","Die Tür ist zu. Wer jetzt noch lernt, tut es freiwillig. Ich sehe weg."]],
 identity:[
  ["Im Buch stehen Sie ab heute als „{w}“. Verdienen Sie es morgen noch einmal.","From today the book lists you as '{w}'. Earn it again tomorrow.","Im Buch stehst du ab heute als „{w}“. Verdien es morgen noch einmal."],
  ["Noch {n} Wörter, dann versteht Bett vier Sie ohne Hände und Füße.","{n} more words and bed four will understand you without hands and feet.","Noch {n} Wörter, dann versteht Bett vier dich ohne Hände und Füße."],
  ["Sie sind kein Schüler, der Arzt spielt. Sie sind ein Arzt, der Deutsch lernt. Benehmen Sie sich so.","You are not a pupil playing doctor. You are a doctor learning German. Behave like one.","Du bist kein Schüler, der Arzt spielt. Du bist ein Arzt, der Deutsch lernt. Benimm dich so."],
  ["Irgendwann fragt Sie eine Pflegerin um drei Uhr nachts etwas auf Deutsch, und Sie antworten, ohne zu merken, dass es Deutsch war. Dafür ist heute.","One night at three a nurse will ask you something in German, and you will answer without noticing that it was German. That is what today is for.","Irgendwann fragt dich eine Pflegerin um drei Uhr nachts etwas auf Deutsch, und du antwortest, ohne zu merken, dass es Deutsch war. Dafür ist heute."]],
 debt:[
  ["Drei Tage: zehn, zwanzig, dreißig. Dann brennt alles. Das ist mein Angebot, und ich mache selten eins.","Three days: ten, twenty, thirty. Then it all burns. That is my offer, and I rarely make one.","Drei Tage: zehn, zwanzig, dreißig. Dann brennt alles. Das ist mein Angebot, und ich mache selten eins."],
  ["Tag {n} von drei. Die Schuldscheine werden nervös.","Day {n} of three. The IOUs are getting nervous.","Tag {n} von drei. Die Schuldscheine werden nervös."],
  ["Ihr Pfand. Unbeschädigt. Ich habe es nur ein wenig angesehen.","Your pledge. Undamaged. I only looked at it a little.","Dein Pfand. Unbeschädigt. Ich habe es nur ein wenig angesehen."]],
 debt_done:[
  ["Heute haben Sie gearbeitet. Das sehe ich. Die {n} Schuldscheine sehe ich auch.","Today you worked. I see that. I see the {n} IOUs as well.","Heute hast du gearbeitet. Das sehe ich. Die {n} Schuldscheine sehe ich auch."],
  ["Fertig für heute, trotz Schulden. Erst die Arbeit, dann die Rechnung. In dieser Reihenfolge mag ich Sie fast.","Done for today, in spite of the debts. Work first, then the bill. In that order I almost like you.","Fertig für heute, trotz Schulden. Erst die Arbeit, dann die Rechnung. In dieser Reihenfolge mag ich dich fast."]],
 after:[
  ["Sie haben einen Vertrag geschrieben, und ich habe unterschrieben. Erzählen Sie es nicht herum.","You wrote a contract and I signed it. Don't spread it about.","Du hast einen Vertrag geschrieben, und ich habe unterschrieben. Erzähl es nicht herum."],
  ["Diese Woche schulde ich Ihnen eine Wahrheit. Halten Sie Ihre Klausel, dann bekommen Sie sie.","This week I owe you a truth. Keep your clause and you get it.","Diese Woche schulde ich dir eine Wahrheit. Halt deine Klausel, dann bekommst du sie."],
  ["Noch {n} Tage bis zur Prüfung. Zwingen kann ich Sie nicht mehr. Ich kann nur noch zusehen. Enttäuschen Sie mich.","{n} days to the exam. I can no longer force you. I can only watch. Disappoint me.","Noch {n} Tage bis zur Prüfung. Zwingen kann ich dich nicht mehr. Ich kann nur noch zusehen. Enttäusch mich."]]
};
