var MEPH8={
 shift_silent:[["Eine Schicht darf schweigen. Eine. Die nächste nicht.","One shift may stay silent. One. Not the next.","Eine Schicht darf schweigen. Eine. Die nächste nicht."]],
 ration_done:[["Ein Schuldschein weniger. Der Tag zählt nicht, aber er ist nicht verloren.","One IOU fewer. The day does not count, but it is not lost.","Ein Schuldschein weniger. Der Tag zählt nicht, aber er ist nicht verloren."]],
 shift_yes:[["Dienst. Eingetragen. Ich glaube Ihnen – diesmal.","A shift. Entered. I believe you — this time.","Dienst. Eingetragen. Ich glaube dir – diesmal."]],
 deal_pause:[["Der Vergleich ruht. Ein Tag Pause ist erlaubt. Zwei Tage sind eine Antwort.","The settlement is resting. One day's pause is allowed. Two days are an answer.","Der Vergleich ruht. Ein Tag Pause ist erlaubt. Zwei Tage sind eine Antwort."]],
 deal_lapsed:[["Der Vergleich ist geplatzt. Kein Drama: Jeder Schuldschein kostet wieder zehn Karten.","The settlement has fallen through. No drama: each IOU costs ten cards again.","Der Vergleich ist geplatzt. Kein Drama: Jeder Schuldschein kostet wieder zehn Karten."]],
 deal_end:[["Alle Schuldscheine verbrannt. Drei Tage, wie versprochen. Ich halte mein Wort. Sie diesmal auch.","All IOUs burned. Three days, as promised. I keep my word. This time so did you.","Alle Schuldscheine verbrannt. Drei Tage, wie versprochen. Ich halte mein Wort. Du diesmal auch."]],
 pfand_none:[["Ihr Kabinett ist leer. Nicht einmal ein Pfand haben Sie. Ich nehme Ihr Wort. Es ist wenig wert.","Your cabinet is empty. You don't even have a pledge. I'll take your word. It is worth little.","Dein Kabinett ist leer. Nicht einmal ein Pfand hast du. Ich nehme dein Wort. Es ist wenig wert."]],
 pfand_taken:[["Verpfändet. Es liegt mit dem Gesicht nach unten bei mir, bis Sie bezahlt haben.","Pledged. It lies face down with me until you have paid.","Verpfändet. Es liegt mit dem Gesicht nach unten bei mir, bis du bezahlt hast."]],
 pen_done:[["Strafe abgesessen. Sie haben sie selbst gewählt, also beschweren Sie sich bei sich.","Punishment served. You chose it yourself, so complain to yourself.","Strafe abgesessen. Du hast sie selbst gewählt, also beschwer dich bei dir."]],
 candle_out:[["Die Kerze ist aus. Zwei gute Wochen, dann zünde ich sie wieder an. Nicht ganz so hoch.","The candle is out. Two good weeks and I'll light it again. Not quite as tall.","Die Kerze ist aus. Zwei gute Wochen, dann zünde ich sie wieder an. Nicht ganz so hoch."]],
 candle_on:[["Die Kerze brennt seit {n} Wochen. Ich habe sie nicht angezündet. Sie schon.","The candle has burned for {n} weeks. I did not light it. You did.","Die Kerze brennt seit {n} Wochen. Ich habe sie nicht angezündet. Du schon."]],
 week_off_none:[["Viermal im Jahr darf man krank sein. Sie waren es schon. Schreiben Sie eine kleine Klausel.","Four times a year one may be ill. You already were. Write a small clause.","Viermal im Jahr darf man krank sein. Du warst es schon. Schreib eine kleine Klausel."]],
 late:[["Zehn Karten. Dann schlafen.","Ten cards. Then sleep.","Zehn Karten. Dann schlafen."]]
};
