// ---- I7 §7.2 — grade lines. Index = grade; [0] grade not worse than last week, [1] worse ({n} counted days, {m} need, {w} weekday of the first missed planned day)
var ZEUGNIS7=[null,
 [["Eins. Klausel gehalten, {n} von {m}. Ich suche den Haken. Ich finde keinen.","A one. Clause kept, {n} of {m}. I'm looking for the catch. I find none.","Eins. Klausel gehalten, {n} von {m}. Ich suche den Haken. Ich finde keinen."],
  ["Wieder eine Eins. Langsam wird es unheimlich. Und ich bin vom Fach.","Another one. This is getting uncanny. And I am in the trade.","Wieder eine Eins. Langsam wird es unheimlich. Und ich bin vom Fach."]],
 [["Zwei, und nicht schlechter als letzte Woche. Sagen Sie nicht „passt“. Sagen Sie: nächste Woche Eins.","A two, and no worse than last week. Don't say 'fine'. Say: next week a one.","Zwei, und nicht schlechter als letzte Woche. Sag nicht „passt“. Sag: nächste Woche Eins."],
  ["Zwei. Letzte Woche war es mehr. Sie wissen, an welchem Tag es lag. Ich auch: {w}.","A two. Last week it was more. You know which day did it. So do I: {w}.","Zwei. Letzte Woche war es mehr. Du weißt, an welchem Tag es lag. Ich auch: {w}."]],
 [["Drei, und die Richtung stimmt. Befriedigend heißt nicht zufrieden.","A three, and the direction is right. Satisfactory does not mean satisfied.","Drei, und die Richtung stimmt. Befriedigend heißt nicht zufrieden."],
  ["Drei, und es geht abwärts. Schreiben Sie die nächste Klausel kleiner – und halten Sie sie.","A three, and falling. Write the next clause smaller — and keep it.","Drei, und es geht abwärts. Schreib die nächste Klausel kleiner – und halt sie."]],
 [["Vier. Es reicht gerade. Aber es ist mehr als letzte Woche, und das notiere ich.","A four. It just suffices. But it is more than last week, and I am noting that.","Vier. Es reicht gerade. Aber es ist mehr als letzte Woche, und das notiere ich."],
  ["Vier. {n} von {m}. Ihre Klausel, nicht meine.","A four. {n} of {m}. Your clause, not mine.","Vier. {n} von {m}. Deine Klausel, nicht meine."]],
 [["Fünf. Besser als nichts. Das ist kein Lob, das ist Mathematik.","A five. Better than nothing. That is not praise, that is arithmetic.","Fünf. Besser als nichts. Das ist kein Lob, das ist Mathematik."],
  ["Fünf. Ich schreie nicht. Wählen Sie diese Woche „Mindestens“ und halten Sie es.","A five. I am not shouting. Choose 'at least' this week and keep it.","Fünf. Ich schreie nicht. Wähl diese Woche „Mindestens“ und halt es."]],
 [["Sechs. Eine Woche ist keine Sprache. Die nächste Klausel liegt vor Ihnen.","A six. One week is not a language. The next clause is in front of you.","Sechs. Eine Woche ist keine Sprache. Die nächste Klausel liegt vor dir."],
  ["Sechs. Den Vertrag habe ich nicht gerahmt. Noch nicht. Zehn Karten.","A six. I have not framed the contract. Not yet. Ten cards.","Sechs. Den Vertrag habe ich nicht gerahmt. Noch nicht. Zehn Karten."]]];
